window.TXB=window.TXB||{};TXB["alab/Exo"]={"1:1":"وهذه هي أسماء أبناء إسرائيل الذين قدموا مع يعقوب إلى مصر، كل واحد منهم مع أهل بيته.","1:2":"رأوبين، وشمعون، ولاوي ويهوذا،","1:3":"ويساكر وزبولون وبنيامين،","1:4":"ودان ونفتالي وجاد وأشير.","1:5":"وكانت جملة النفوس المولودين من صلب يعقوب سبعين نفسا. أما يوسف فقد كان في مصر.","1:6":"ثم مات يوسف وإخوته جميعا وكذلك سائر ذلك الجيل.","1:7":"ونما بنو إسرائيل، وتوالدوا وتكاثروا وعظموا جدا حتى اكتظت بهم الأرض.","1:8":"وما لبث أن قام ملك جديد على مصر لم يكن يعرف يوسف.","1:9":"فقال لشعبه: «ها بنو إسرائيل أكثر منا وأعظم قوة.","1:10":"فلنتآمر عليهم لكيلا يتكاثروا وينضموا إلى أعدائنا إذا نشب قتال ويحاربونا ثم يخرجوا من الأرض».","1:11":"فعهدوا بهم إلى مشرفين عتاة ليسخروهم بالأعمال الشاقة. فبنوا مدينتي فيثوم ورعمسيس لتكونا مخازن لفرعون.","1:12":"ولكن كلما زادوا من إذلالهم، ازداد تكاثرهم ونموهم، فتخوفوا من بني إسرائيل","1:13":"فتزايد عنف استعباد المصريين لبني إسرائيل.","1:14":"وأتعسوا حياتهم بالأعمال الشاقة في الطين واللبن كادحين في الحقول. وسخرهم المصريون بعنف في كل أعمالهم الشاقة.","1:15":"ثم قال ملك مصر للقابلتين العبرانيتين المدعوتين شفرة وفوعة:","1:16":"«عندما تشرفان على توليد النساء العبرانيات راقباهن على كرسي الولادة، فإن كان المولود صبيا فاقتلاه، وإن كان بنتا فاتركاها تحيا.","1:17":"غير أن القابلتين كانتا تخافان الله فلم تنفذا أمر الملك فاستحيتا الأطفال الذكور.","1:18":"فاستدعى ملك مصر القابلتين وسألهما: «لماذا فعلتما هذا الأمر واستحييتما الأطفال الذكور؟»","1:19":"فأجابتاه: «إن النساء العبرانيات لسن كالمصريات، فإنهن قويات يلدن قبل وصول القابلة إليهن».","1:20":"وتكاثر الشعب وعظم جدا.","1:21":"وإذ خافت القابلتان الله أثابهما بنسل.","1:22":"ثم أصدر فرعون أمره لجميع شعبه قائلا: «اطرحوا كل ابن (عبراني) يولد في النهر، أما البنات فاستحيوهن».","2:1":"وتزوج رجل من بيت لاوي فتاة ابنة لاوي.","2:2":"فحملت المرأة وأنجبت ابنا، وإذ راقها جماله خبأته ثلاثة أشهر.","2:3":"ولما لم تستطع أن تخفيه بعد، أتت بسلة من البردي وطلته بالحمر والزفت وأضجعت الطفل ووضعته بين الحلفاء على ضفة النهر.","2:4":"ووقفت أخته من بعيد لترى ما يحدث له.","2:5":"وأقبلت ابنة فرعون لتستحم في النهر، بينما راحت وصيفاتها تتمشين على ضفة النهر. فرأت السلة بين الحلفاء فأرسلت وصيفتها لتأتي به.","2:6":"ففتحته ورأت الطفل وإذا هو يبكي، فرقت له وقالت: «هذا من أولاد العبرانيين»","2:7":"فقالت أخته لابنة فرعون: «هل أذهب وأدعو لك مرضعة من العبرانيات لترضع لك الولد؟»","2:8":"فأجابتها ابنة فرعون: «اذهبي»؛ فمضت الفتاة ودعت أم الصبي.","2:9":"فقالت لها ابنة فرعون: «خذي هذا الصبي وأرضعيه لي، وأنا أعطيك أجرتك». فأخذت المرأة الصبي وأرضعته.","2:10":"ولما كبر الولد، ردته إلى ابنة فرعون فتبنته ودعته موسى (ومعناه منتشل) قائلة: «إني انتشلته من الماء».","2:11":"وحدث بعد أن كبر موسى أنه ذهب ليفتقد إخوته العبرانيين ويشهد مشقتهم، فلمح رجلا مصريا يضرب رجلا عبرانيا،","2:12":"فتلفت حوله، وإذ لم يجد أحدا هناك قتل المصري وطمره في الرمل.","2:13":"ثم خرج في اليوم الثاني وإذا رجلان عبرانيان يتضاربان، فقال للمسيء: «لماذا تضرب صاحبك؟»","2:14":"فأجابه: «من أقامك رئيسا وقاضيا علينا؟ أعازم أنت على قتلي كما قتلت المصري؟» فخاف موسى وقال: «حقا إن الخبر قد ذاع».","2:15":"وبلغ الخبر مسمع فرعون، فسعى إلى قتل موسى، إلا أن موسى هرب من وجه فرعون، ومضى ليقيم في أرض مديان، فبلغها وجلس عند البئر.","2:16":"وكان لكاهن مديان سبع فتيات فأقبلن واستقين ماء وملأن الأجران ليسقين غنم أبيهن.","2:17":"فأتى الرعاة وطردوهن. غير أن موسى هب لنجدتهن وسقى غنمهن.","2:18":"وعندما رجعت الفتيات إلى رعوئيل أبيهن سألهن: «ما بالكن بكرتن بالرجوع اليوم؟»","2:19":"فأجبنه: «رجل مصري أنقذنا من أيدي الرعاة، فاستقى لنا ولغنمنا أيضا».","2:20":"فسألهن: «وأين هو؟ لماذا تركتن الرجل؟ ادعونه ليأكل طعاما».","2:21":"وقبل موسى أن يقيم مع الرجل الذي زوجه من ابنته صفورة.","2:22":"فأنجبت له ابنا دعاه جرشوم (ومعناه غريب) إذ قال: «كنت نزيلا في أرض غريبة».","2:23":"وبعد مرور حقبة طويلة مات ملك مصر. وارتفع أنين بني إسرائيل وصراخهم من وطأة العبودية، وصعد إلى الله.","2:24":"فأصغى الله إلى أنينهم، وتذكر عهده مع إبراهيم وإسحق ويعقوب.","2:25":"ونظر الله إلى بني إسرائيل (ورق لحالهم).","3:1":"وأما موسى فكان يرعى غنم حميه يثرون كاهن مديان، فقاد الغنم إلى ما وراء الطرف الأقصى من الصحراء حتى جاء إلى حوريب جبل الله.","3:2":"وهناك تجلى له ملاك الرب بلهيب نار وسط عليقة. فنظر موسى وإذا بالعليقة تتقد دون أن تحترق.","3:3":"فقال موسى: «أميل الآن لأستطلع هذا الأمر العظيم. لماذا لا تحترق العليقة؟»","3:4":"وعندما رأى الرب أن موسى قد دنا ليستطلع الأمر، ناداه من وسط العليقة قائلا: «موسى». فقال: «ها أنا».","3:5":"فقال: «لا تقترب إلى هنا: اخلع حذاءك من رجليك، لأن المكان الذي أنت واقف عليه أرض مقدسة».","3:6":"ثم قال: «أنا هو إله أبيك، إله إبراهيم، وإله إسحق، وإله يعقوب». عندئذ غطى موسى وجهه خوفا من أن يرى الله (فيموت).","3:7":"فقال الرب: «قد شهدت مذلة شعبي الذي في مصر وسمعت صراخهم من جراء عتو مسخريهم وأدركت معاناتهم،","3:8":"فنزلت لأنقذهم من يد المصريين وأخرجهم من تلك الأرض إلى أرض طيبة رحيبة تفيض لبنا وعسلا، أرض الكنعانيين والحثيين والأموريين والفرزيين والحويين واليبوسيين.","3:9":"وها هو الآن قد وصل إلي صراخ بني إسرائيل، ورأيت كيف يضايقهم المصريون.","3:10":"فهلم الآن لأرسلك إلى فرعون، فتخرج شعبي بني إسرائيل من مصر».","3:11":"فقال موسى لله: «من أنا حتى أمضي إلى فرعون وأخرج بني إسرائيل من مصر؟»","3:12":"فأجاب: «أنا أكون معك. ومتى أخرجت الشعب من مصر تعبدون الله على هذا الجبل، فتكون هذه لك العلامة أنني أنا أرسلتك».","3:13":"فقال موسى لله: «حينما أقبل على بني إسرائيل وأقول لهم: إن إله آبائكم قد بعثني إليكم وسألوني: ما اسمه؟ فماذا أقول لهم؟»","3:14":"فأجابه الله: «أهيه الذي أهيه» (ومعناه أنا الكائن الدائم). وأضاف: «هكذا تقول لبني إسرائيل: «أهيه (أنا الكائن)، هو الذي أرسلني إليكم».","3:15":"وقال أيضا لموسى: «هكذا تقول لشعب إسرائيل: إن الرب «الكائن» إله آبائكم، إله إبراهيم وإسحق ويعقوب قد أرسلني إليكم. هذا هو اسمي إلى الأبد، وهو الاسم الذي أدعى به من جيل إلى جيل.","3:16":"اذهب واجمع شيوخ إسرائيل وقل لهم: إن الرب إله آبائكم، إله إبراهيم وإسحق ويعقوب قد تجلى لي قائلا: إنني حقا قد تفقدتكم، وشهدت ما أصابكم في مصر،","3:17":"وها أنا قد وعدت أن أخرجكم من ضيقة مصر إلى أرض الكنعانيين والحثيين والأموريين والفرزيين والحويين واليبوسيين، هذه الأرض التي تفيض لبنا وعسلا،","3:18":"فيستمع الشيوخ لكلامك فتمثل أنت وشيوخ إسرائيل أمام ملك مصر وتقول له: إن الرب إله العبرانيين قد تفقدنا، فدعنا نمضي مسيرة ثلاثة أيام في البرية ونقدم ذبائح للرب إلهنا.","3:19":"ولكنني عالم أن ملك مصر لن يطلقكم ما لم ترغمه يد قوية.","3:20":"فأمد يدي وأضرب مصر بجميع ويلاتي التي أصنعها فيها، وبعد ذلك يطلقكم.","3:21":"وأجعل هذا الشعب يحظى برضى المصريين، فلا تخرجون فارغين حين تمضون،","3:22":"بل تطلب كل امرأة من جارتها أو نزيلة بيتها جواهر فضة وذهب وثيابا تلبسونها بنيكم وبناتكم فتغنمون ذلك من المصريين».","4:1":"فقال موسى: «ماذا إذا لم يصدقوني ولم يصغوا إلي وقالوا: إن الرب لم يظهر لك؟»","4:2":"فسأله الرب: «ما تلك التي بيدك؟» فأجاب: «عصا».","4:3":"فقال: «ألقها على الأرض». فألقاها فإذا هي حية، فهرب منها موسى.","4:4":"فقال الرب لموسى: «مد يدك واقبض عليها من ذيلها». فمد موسى يده وقبض عليها، فارتدت عصا في يده.","4:5":"وقال الرب: «هذا لكي يؤمنوا أن الرب إله آبائكم، إله إبراهيم وإله إسحق وإله يعقوب قد ظهر لك».","4:6":"ثم قال الرب أيضا: «أدخل يدك في عبك». فأدخل يده في عبه. وعندما أخرجها إذا بها برصاء كالثلج.","4:7":"وأمره الرب: «رد يدك إلى عبك ثانية». فرد يده إلى عبه ثانية ثم أخرجها من عبه، وإذا بها قد عادت مثل باقي جسده.","4:8":"وقال الرب: «إذا لم يصدقوك، أو يعيروا المعجزة الأولى انتباههم، فإنهم يصدقون الثانية.","4:9":"وإذا لم يصدقوا هاتين الآيتين ولم يصغوا لكلامك، فاغرف من ماء النهر واسكبه على الأرض الجافة، فيتحول الماء الذي غرفته من النهر إلى دم فوق الأرض».","4:10":"فقال موسى للرب: «أصغ يا رب، أنا لم أكن في يوم من الأيام فصيحا، لا في الأمس، ولا منذ أن خاطبت عبدك. إنما أنا بطيء النطق عيي اللسان».","4:11":"فقال الرب له: «من هو بارئ فم الإنسان؟ أو من يجعله أخرس أو أصم أو بصيرا أو كفيفا؟ ألست أنا، الرب؟","4:12":"فالآن انطلق فألقن فمك النطق، وأعلمك ماذا تقول».","4:13":"لكن موسى أجاب: «يا سيد، أتوسل إليك أن ترسل من تشاء غيري».","4:14":"فاحتدم غضب الرب على موسى وقال: «أليس هرون اللاوي أخاك؟ أنا أعلم أنه يحسن الكلام، وها هو أيضا قادم للقائك. وحالما يراك يبتهج قلبه.","4:15":"فتحدثه وتلقن فمه الكلام، فأعينكما على القول، وأعلمكما ماذا تفعلان،","4:16":"فيخاطب هو الشعب عنك ويكون لك بمثابة فم وأنت تكون له بمثابة إله.","4:17":"وخذ بيدك هذه العصا لتصنع بها المعجزات».","4:18":"فرجع موسى إلى يثرون حميه وقال له: «دعني أعود إلى قومي في مصر لأرى أما زالوا بعد أحياء». فأجاب يثرون موسى: «اذهب بسلام».","4:19":"وأمر الرب موسى في مديان: «هيا ارجع إلى مصر، فإنه قد مات جميع الساعين إلى القضاء عليك».","4:20":"فأخذ موسى امرأته وبنيه وأركبهم على الحمير ومضى عائدا إلى أرض مصر. وأخذ معه عصا الله أيضا.","4:21":"وقال الرب لموسى: «حالما ترجع إلى مصر، تذكر أن تجري أمام فرعون جميع العجائب التي منحتك القوة على إجرائها، ولكنني سأقسي قلبه لكي لا يطلق الشعب.","4:22":"ثم قل لفرعون: هذا ما يقوله الرب: إسرائيل هو ابني البكر.","4:23":"قلت لك: أطلق ابني ليعبدني، ولكنك رفضت إطلاقه، لذلك سأهلك ابنك البكر»","4:24":"وفي أثناء الطريق، بالقرب من خان، التقاه الرب وهم أن يقتله.","4:25":"فأخذت صفورة صوانة وقطعت قلفة ابنها ومست بها قدمي موسى قائلة: «حقا إنك عريس دم لي».","4:26":"فعفا الرب عنه. حينئذ قالت: «عريس دم من أجل الختان».","4:27":"وقال الرب لهرون: «اذهب إلى الصحراء لاستقبال موسى». فمضى والتقاه عند جبل الرب وقبله.","4:28":"فأطلع موسى هرون على جميع كلام الرب الذي حمله إياه، وما كلفه به من آيات،","4:29":"ثم انطلق موسى وهرون وجمعا كل شيوخ بني إسرائيل،","4:30":"فحدثهم هرون بجميع ما قاله الرب لموسى. وأجرى موسى المعجزات أمامهم.","4:31":"فآمن الشعب. وعندما سمعوا أن الله قد افتقدهم ونظر إلى مذلتهم انحنوا ساجدين.","5:1":"وبعد ذلك ذهب موسى وهرون وقالا لفرعون: «هذا ما يعلنه الرب إله إسرائيل: أطلق شعبي ليحتفل لي في البرية».","5:2":"فقال فرعون: «من هو الرب حتى أطيع أمره وأطلق إسرائيل؟ أنا لا أعرف الرب ولن أطلق بني إسرائيل».","5:3":"ثم قالا: «إن إله العبرانيين قد التقانا، فدعنا نذهب مسيرة ثلاثة أيام في الصحراء لنقدم ذبائح للرب إلهنا لئلا يعاقبنا بوبأ أو سيف».","5:4":"فقال لهما ملك مصر: «يا موسى وهرون، لماذا تعطلان الشعب عن أعماله؟ ارجعوا إلى أعمالكم الشاقة».","5:5":"ثم قال فرعون: «هوذا شعب الأرض قد كثر الآن، وأنتما تريدان أن تريحاهم من الأعمال الشاقة».","5:6":"في ذلك اليوم أمر فرعون القائمين على تسخير الشعب ورؤساء العمال قائلا:","5:7":"«كفوا عن إعطاء الشعب تبنا لصنع اللبن كما كنتم تفعلون سابقا، وليذهبوا هم ويجمعوا تبنا لأنفسهم.","5:8":"وطالبوهم بإنتاج نفس كمية اللبن السابقة. لا تنقصوها فإنهم كسالى، لذلك يصرخون قائلين: دعنا نذهب ونذبح لإلهنا.","5:9":"ثقلوا العمل على كواهل القوم حتى يشتغلوا به ولا يلتفتوا إلى الأقوال الكاذبة».","5:10":"فخرج مسخرو الشعب ورؤساء العمال وخاطبوا الشعب قائلين: «هكذا يقول فرعون: لن أعطيكم تبنا.","5:11":"اذهبوا أنتم واجمعوا لأنفسكم تبنا حيث تجدونه على ألا ينقص إنتاجكم».","5:12":"فتفرق الشعب في كل أرض مصر ليجمعوا قشا بدلا من التبن.","5:13":"وكان المسخرون يلحون عليهم قائلين: «أوفوا أعمالكم، إنتاج كل يوم بيومه كما كان الحال حين توافر التبن».","5:14":"وجلد مسخرو فرعون رؤساء العمال الذين أقاموهم على بني إسرائيل قائلين لهم: «لماذا لم توفوا قسطكم من إنتاج اللبن أمس واليوم كما كنتم تفعلون سابقا؟»","5:15":"فأقبل رؤساء عمال بني إسرائيل وتوسلوا إلى فرعون قائلين: «لماذا تفعل هكذا بعبيدك؟","5:16":"إن عبيدك لا يحصلون على التبن، ومطالبون بكمية اللبن نفسها، ويجلد عبيدك أيضا. ولكن الذنب هو ذنب شعبك».","5:17":"غير أنه قال: «أنتم كسالى، لذلك تقولون: دعنا نذهب لنذبح للرب.","5:18":"هيا اذهبوا واعملوا، فالتبن لن يعطى لكم، وعليكم أن تنتجوا كامل كمية اللبن نفسها».","5:19":"فوجد رؤساء عمال بني إسرائيل أنفسهم في ورطة سيئة بعد أن قيل لهم أنتجوا من لبنكم فريضة كل يوم بيومه. لا تنقصوا منها شيئا","5:20":"وصادفوا موسى وهرون وهما واقفان في انتظارهم عند خروجهم من لدن فرعون","5:21":"فقالوا لهما: «لينظر إليكما الرب ويقض. لقد كرهتما فينا فرعون وحاشيته، وأعطيتماهم سيفا في أيديهم ليقتلونا».","5:22":"فرجع موسى إلى الرب وقال: «لماذا أسأت إلى شعبك يا رب؟ لماذا أرسلتني؟","5:23":"فمنذ أن جئت لأخاطب فرعون باسمك، أساء إلى الشعب، وأنت لم تخلص شعبك على الإطلاق».","6:1":"فأجاب الرب موسى: «سترى الآن ما أنا فاعله بفرعون، لأنني بيد قديرة سأجعله يطلقهم، بل يطردهم طردا أيضا».","6:2":"وقال الرب لموسى: «أنا هو الرب.","6:3":"قد ظهرت لإبراهيم وإسحق ويعقوب إلها قديرا على كل شيء. أما اسمي يهوه (أي الرب) فلم أعلنه لهم.","6:4":"وقد قطعت معهم أيضا عهدي بأن أهبهم أرض كنعان حيث أقاموا فيها كغرباء.","6:5":"كذلك أصغيت إلى أنين بني إسرائيل المستعبدين المصريين، وتذكرت عهدي","6:6":"لهذا قل لبني إسرائيل إنني أنا الرب وأنا أحرركم من أثقال المصريين وأنقذكم من عبوديتهم، وأخلصكم بذراع ممدودة وأحكام قوية.","6:7":"وأتخذكم لي شعبا وأكون لكم إلها، فتعرفون أني أنا الرب إلهكم محرركم من أثقال المصريين.","6:8":"وأقودكم إلى الأرض التي أقسمت أن أهبها لإبراهيم وإسحق ويعقوب لأعطيها لكم ملكا. أنا هو الرب».","6:9":"فخاطب موسى بني إسرائيل، لكنهم لم يصغوا إليه لتوجع نفوسهم وعبوديتهم القاسية.","6:10":"وقال الرب لموسى:","6:11":"«امثل أمام فرعون ملك مصر واطلب إليه أن يطلق بني إسرائيل من الأرض».","6:12":"فأجاب موسى: «هوذا بنو إسرائيل لم يصغوا إلي، فكيف يستمع إلي فرعون وأنا ثقيل اللسان؟»","6:13":"فخاطب الرب موسى وهرون وأمرهما أن يرجعا إلى بني إسرائيل، وفرعون ملك مصر، لكي يطلق بني إسرائيل من أرض مصر.","6:14":"وهؤلاء هم رؤساء العشائر المتفرعة عن أبناء إسرائيل: أبناء رأوبين بكر إسرائيل حنوك وفلو وحصرون وكرمي: هذه عشائر رأوبين.","6:15":"أبناء شمعون يموئيل ويامين وأوهد وياكين وصوحر وشأول وأمه كنعانية: هذه هي عشائر شمعون.","6:16":"وهذه أسماء أبناء لاوي حسب عشائرهم: جرشون وقهات ومراري. وقد عاش لاوي مئة وسبعا وثلاثين سنة.","6:17":"أما ابنا جرشون حسب عشائرهما فهما: لبني وشمعي.","6:18":"وأبناء قهات هم: عمرام ويصهار وحبرون وعزيئيل. وقد عاش قهات مئة وثلاثا وثلاثين سنة.","6:19":"وابنا مراري هما محلي وموشي. هذه هي عشائر اللاويين بحسب سجل مواليدهم.","6:20":"وتزوج عمرام عمته يوكابد فأنجبت له هرون وموسى. وقد عاش عمرام مئة وسبعا وثلاثين سنة.","6:21":"وأبناء يصهار هم: قورح ونافج وذكري.","6:22":"أبناء عزيئيل هم: ميشائيل وألصافان وستري","6:23":"وتزوج هرون من أليشابع ابنة عميناداب أخت نحشون فأنجبت له ناداب وأبيهو وألعازار وإيثامار.","6:24":"وأبناء قورح هم: أسير وألقانة وأبيأساف: هذه هي عشائر القورحيين.","6:25":"وتزوج ألعازار بن هرون من إحدى بنات فوطيئيل فأنجبت له فينحاس. هؤلاء رؤساء آباء اللاويين بحسب ترتيب عشائرهم.","6:26":"هذان هما هرون وموسى اللذان قال لهما الرب: أخرجا بني إسرائيل من أرض مصر بحسب فرقهم.","6:27":"وهما نفس موسى وهرون اللذين خاطبا فرعون ملك مصر ليطلق بني إسرائيل من مصر.","6:28":"وحدث في اليوم الذي كلم فيه الرب موسى في أرض مصر","6:29":"أن الرب قال له: «أنا الرب بلغ فرعون كل ما أقوله لك».","6:30":"فأجابه موسى: «أنا ثقيل اللسان فكيف يستمع لي فرعون؟»","7:1":"فقال الرب لموسى: «أنا جعلتك كإله لفرعون، وهرون أخوك يكون كنبي لك.","7:2":"فعليك أن تبلغه بكل ما آمرك به، ويخاطب أخوك هرون فرعون كي يطلق سراح بني إسرائيل من بلاده.","7:3":"ولكنني أقسي قلب فرعون فأكثر آياتي وعجائبي في أرض مصر.","7:4":"إلا أن فرعون لن يستمع لكما. عندئذ أضرب مصر وأخرج شعبي إسرائيل من أرض مصر بقوات أحكام عظيمة.","7:5":"فيدرك المصريون حين أضرب مصر وأخرج بني إسرائيل من بينهم أنني أنا الرب».","7:6":"ففعل موسى وهرون تماما كما أمرهما الرب.","7:7":"وكان موسى في الثمانين من عمره، وهرون في الثالثة والثمانين، عندما خاطبا فرعون.","7:8":"وقال الرب لموسى وهرون:","7:9":"«عندما يطلب فرعون منكما قائلا: أرياني عجيبة فإنك تقول لهرون: خذ عصاك وألقها أمام فرعون فتتحول إلى حية».","7:10":"فمثل هرون وموسى أمام فرعون وفعلا تماما حسب أمر الرب، فألقى هرون عصاه أمام فرعون وأمام حاشيته فتحولت إلى حية.","7:11":"فاستدعى فرعون حكماءه وسحرته فصنع سحرة مصر على غرار ذلك بسحرهم.","7:12":"فطرح كل واحد عصاه فتحولت إلى حية. غير أن عصا هرون ابتلعت عصيهم.","7:13":"لكن قلب فرعون ازداد تصلبا فلم يستمع لهما، تماما كما قال الرب.","7:14":"ثم قال الرب لموسى: «إن قلب فرعون قد تصلب، وهو يرفض أن يطلق سراح الشعب.","7:15":"فامثل أمام فرعون في الغد عندما يخرج إلى الماء، وقف للقائه عند ضفة النهر، وخذ بيدك العصا التي تحولت إلى حية،","7:16":"وقل له: إن الرب إله العبرانيين قد أرسلني إليك قائلا: أطلق شعبي ليعبدوني في الصحراء. وها أنت حتى الآن لم تستمع.","7:17":"لهذا إليك ما يقوله الرب: ستعلم، بما أجريه الآن، أنني أنا الرب. ها أنا ضارب بهذه العصا التي في يدي على ماء النهر فيتحول دما.","7:18":"فيموت السمك، وينتن النهر، فيعاف المصريون من الشرب من مائه».","7:19":"وخاطب الرب موسى: «قل لهرون: خذ عصاك وابسط يدك على مياه المصريين وعلى أنهارهم وعلى جداولهم وسواقيهم وخزانات المياه فتتحول كلها إلى دم، ويكون دم في كل أرض مصر حتى في الأواني الخشبية والحجرية».","7:20":"وهكذا فعل موسى وهرون كما أمر الرب، فرفع هرون العصا وضرب ماء النهر على مشهد من فرعون وحاشيته فتحول كل ماء النهر إلى دم،","7:21":"ومات كل سمكه وأنتن النهر فلم يستطع المصريون الشرب من مائه. وكان دم في كل أرجاء أرض مصر.","7:22":"وكذلك فعل سحرة مصر بسحرهم، فتصلب قلب فرعون فلم يستمع إليهما، تماما حسب قول الرب.","7:23":"وانصرف فرعون إلى منزله من غير أن يترك ذلك أثرا في قلبه.","7:24":"وحفر جميع المصريين حفرا حول النهر طلبا لماء الشرب، لأنهم لم يستطيعوا أن يشربوا من ماء النهر.","7:25":"وانقضت سبعة أيام منذ أن ضرب الله مياه النهر.","8:1":"ثم قال الرب لموسى: «امثل أمام فرعون وقل له: هذا ما يعلنه الرب: أطلق شعبي ليعبدوني.","8:2":"وإن أبيت أن تطلقهم فها أنا ضارب جميع تخومك بالضفادع.","8:3":"فيفيض النهر بالضفادع التي تصعد وتقتحم بيتك ومخدع فراشك وسريرك وبيوت حاشيتك وشعبك وأفرانك ومعاجنك.","8:4":"عليك وعلى شعبك وعلى سائر حاشيتك تصعد الضفادع».","8:5":"ثم قال الرب لموسى: «قل لهرون أبسط يدك بعصاك على الأنهار والسواقي والبرك وأصعد الضفادع على كل أرض مصر».","8:6":"فبسط هرون يده على مياه مصر فأقبلت الضفادع وغطت أرض مصر.","8:7":"وكذلك فعل السحرة بسحرهم فأصعدوا ضفادع على أرض مصر.","8:8":"ثم استدعى فرعون موسى وهرون وقال: «تضرعا إلى الرب ليرفع الضفادع عني وعن شعبي، فأطلق الشعب ليقدموا ذبائح له».","8:9":"فأجاب موسى فرعون: «عين لي متى أصلي من أجلك ومن أجل عبيدك وشعبك، لكي تباد الضفادع عنك وعن بيوتك، ما عدا تلك الباقية في النهر».","8:10":"فقال فرعون: «غدا». فأجابه موسى: «فليكن كقولك، لتعرف أنه لا مثيل للرب إلهنا.","8:11":"فإن الضفادع ستنسحب من حولك ومن بيوتك ومن حول حاشيتك وشعبك، ولا تبقى إلا في النهر».","8:12":"وبعد أن انصرف موسى وهرون من لدن فرعون صلى موسى إلى الرب من أجل الضفادع التي أصعدها على فرعون،","8:13":"ففعل الرب حسب دعاء موسى، فانقطعت الضفادع من البيوت والدور والحقول،","8:14":"فجمعوها أكواما كثيرة حتى أنتنت منها الأرض.","8:15":"وعندما رأى فرعون أن البلية قد انقشعت، أغلظ قلبه ولم يستمع لهما، تماما كما قال الرب.","8:16":"فقال الرب لموسى: «قل لهرون أن يبسط يده بعصاه ويضرب تراب الأرض ليملأ البعوض كل أرجاء مصر».","8:17":"وهكذا فعلا، إذ بسط هرون يده بعصاه وضرب تراب الأرض، فانتشر البعوض على الناس والبهائم. فصار كل تراب الأرض بعوضا في جميع أرجاء مصر.","8:18":"وكذلك حاول السحرة بسحرهم ليخرجوا البعوض فأخفقوا. وكان البعوض منتشرا على الناس والبهائم.","8:19":"فقال السحرة لفرعون «إنه فعل الله». ولكن قلب فرعون ظل متصلبا فلم يسمع لهما، تماما كما قال الرب.","8:20":"ثم قال الرب لموسى: «انهض مبكرا في الصباح وقف أمام فرعون عند خروجه إلى الماء وقل له: هكذا يقول الرب: أطلق شعبي ليعبدوني.","8:21":"وإن لم تطلق شعبي فها أنا أرسل أسراب الذباب عليك وعلى حاشيتك وعلى شعبك وعلى بيوتك، فتمتلئ بيوت المصريين بالذباب، وكذلك الأرض التي يقيمون عليها.","8:22":"ولكني في ذلك اليوم أستثني أرض جاسان حيث يسكن شعبي فلا يغزوها الذباب، فتدرك أنني، أنا الرب، كائن في هذه الأرض.","8:23":"وأميز بين شعبي وشعبك، فتكون هذه آية الغد».","8:24":"وهكذا صنع الرب، فقد غزت أسراب عظيمة من الذباب بيت فرعون وبيوت حاشيته، وكل أرض مصر فأصاب الذباب الأرض بالخراب.","8:25":"فاستدعى فرعون موسى وهرون وقال: «امضوا وقدموا ذبيحة لإلهكم في هذه الأرض».","8:26":"فأجاب موسى: «ليس مستحسنا أن نفعل هذا، لأن الذبائح التي نقدمها للرب إلهنا هي رجس لدى المصريين. فإن قدمنا هذه الذبائح التي يكرهها المصريون، ألا يرجموننا؟","8:27":"لكن نذهب مسيرة ثلاثة أيام في الصحراء، فنقدم ذبائح للرب إلهنا كما أمرنا».","8:28":"فقال فرعون: «سأطلقكم لتقربوا للرب إلهكم في الصحراء، ولكن لا تذهبوا بعيدا. صليا لأجلي».","8:29":"فأجاب موسى: «حالما أنصرف أصلي إلى الرب. وغدا يرتفع الذباب عن فرعون وعن حاشيته وعن شعبه. ولكن على فرعون ألا يخادع، بل يطلق الشعب ليقدم للرب ذبائح».","8:30":"وفارق موسى فرعون وصلى إلى الرب،","8:31":"فاستجاب الرب دعاء موسى، فارتفع الذباب عن فرعون وعن حاشيته وعن شعبه. لم تبق ذبابة واحدة.","8:32":"ولكن فرعون قسى قلبه هذه المرة أيضا ولم يطلق الشعب.","9:1":"ثم قال الرب لموسى: «امض إلى فرعون وقل له: هذا ما يعلنه إله العبرانيين أطلق شعبي ليعبدني.","9:2":"لأنك إن أبيت أن تطلقهم وحجزتهم لديك،","9:3":"فإن يد الرب ستهلك مواشيك التي في الحقول، والخيول، والحمير والجمال والثيران والغنم، بوبأ شديد جدا.","9:4":"وأميز بين مواشي إسرائيل ومواشي المصريين. فلا يهلك شيء لبني إسرائيل».","9:5":"وعين الرب موعدا لذلك قائلا: «غدا يصنع الرب هذا في الأرض».","9:6":"وفي الغد صنع الرب هذا الأمر. فهلكت جميع مواشي المصريين، أما مواشي بني إسرائيل فلم يهلك منها واحد.","9:7":"وأرسل فرعون ليتحقق من الأمر، وإذا مواشي إسرائيل لم يهلك منها واحد. وتصلب قلب فرعون فلم يطلق الشعب.","9:8":"فقال الرب لموسى وهرون: «ليأخذ كل منكما حفنة من رماد الأتون، وليذر موسى الرماد نحو السماء بمرأى من فرعون،","9:9":"فيتحول إلى غبار يغطي كل أرض مصر، فيصاب الناس والبهائم بدمامل متقيحة في كل أرض مصر».","9:10":"فأخذا رمادا من الأتون، ووقفا أمام فرعون، ثم ذراه موسى نحو السماء، فتحول إلى دمامل متقيحة أصابت الناس والبهائم.","9:11":"ولم يستطع السحرة أن يواجهوا موسى من جراء الدمامل، لأن الدمامل أصابت السحرة وكل المصريين أيضا.","9:12":"لكن الرب قسى قلب فرعون فلم يسمع لهما، تماما كما قال الرب لموسى.","9:13":"ثم قال الرب لموسى: «قم مبكرا في الصباح وامثل أمام فرعون وقل له: هذا ما يعلنه الرب إله العبرانيين: أطلق شعبي ليعبدني.","9:14":"لأنني في هذه المرة سأوجه جميع ضرباتي إلى قلبك وإلى حاشيتك وإلى شعبك، لكي تعرف أنه ليس مثيل لي في كل الأرض.","9:15":"فقد كان بوسعي حتى الآن أن أمد يدي وأضربك وأضرب شعبك أيضا بالوبأ لتباد من الأرض،","9:16":"ولكنني أقمتك لأريك قوتي، ولكي يذاع اسمي في جميع الأرض.","9:17":"وها أنت مازلت تقاوم شعبي ولا تطلقه.","9:18":"لذلك غدا في مثل هذا الوقت أمطر بردا ثقيلا لم تشهده مصر منذ يوم تأسيسها حتى الآن.","9:19":"فأرسل الآن واجمع مواشيك وكل مالك في الحقل، لأن كل من يمكث في الحقل من الناس والبهائم ولا يلجأ إلى مأوى، ينهمر عليه البرد فيموت».","9:20":"فكل من خاف كلمة الرب من رجال فرعون لاذ بعبيده وماشيته بالبيوت،","9:21":"أما الذين استخفوا بكلام الرب فقد تركوا عبيدهم ومواشيهم في الحقل.","9:22":"وقال الرب لموسى: «مد يدك نحو السماء فينهمر البرد على كل أرض مصر، وعلى الرجال والبهائم وعلى عشب الحقل في جميع أرض مصر».","9:23":"فمد موسى عصاه نحو السماء، فأرسل الرب رعودا وبردا. وأصابت الصواعق الأرض، وأمطر الرب بردا على كل بلاد مصر،","9:24":"فانهمر البرد، واختلطت الصواعق بالبرد، فكانت أسوأ عاصفة شهدتها أرض مصر منذ أن صارت أمة.","9:25":"وأصاب البرد في كل أرجاء مصر جميع ما في الحقول من ناس وبهائم. وأتلف كل نبات نام في الحقل وكسر جميع الأشجار.","9:26":"أما أرض جاسان حيث يقيم بنو إسرائيل، فإنها وحدها لم يسقط فيها برد.","9:27":"فأرسل فرعون واستدعى موسى وهرون وقال لهما: «لقد أخطأت هذه المرة والرب هو البار، أما أنا وشعبي فأشرار،","9:28":"فتضرعا إلى الرب إذ يكفينا ما ابتلينا به من رعود وبرد، فأطلقكم، ولا تمكثون هنا بعد».","9:29":"فأجاب موسى: «حالما أخرج من المدينة أبسط يدي في الصلاة إلى الرب فيتوقف الرعد وينقطع البرد لكي تعرف أن الأرض هي للرب.","9:30":"ولكنني عالم أنك أنت وحاشيتك مازلتم لا تخشون الرب الإله.","9:31":"إن الكتان والشعير قد تلفا، لأن الشعير أصبح سنابل، والكتان كان مبزرا،","9:32":"أما الحنطة والقطاني فلم تتلف بعد لأنها تنمو متأخرة».","9:33":"وانصرف موسى من لدن فرعون من المدينة وبسط يديه إلى الرب، فتوقف الرعد والبرد وانقطع المطر عن الانهمار على الأرض.","9:34":"وعندما رأى فرعون أن المطر والبرد والرعد قد توقفت أخطأ مرة أخرى وصلب قلبه هو وحاشيته.","9:35":"وهكذا تقسى قلب فرعون، فلم يطلق بني إسرائيل، تماما كما أنبأ الرب على لسان موسى.","10:1":"وقال الرب لموسى: «امثل أمام فرعون لأنني قد قسيت قلبه وقلوب حاشيته لكي أجري آياتي هذه بينهم.","10:2":"لكي تخبر في مسامع بنيك وأحفادك عما ابتليت به المصريين وبآياتي التي أجريتها بينهم فتعلمون أني أنا الرب».","10:3":"فمثل موسى وهرون أمام فرعون وقالا له: «هذا ما يعلنه الرب إله العبرانيين: إلى متى تأبى أن تخضع لي؟ أطلق شعبي ليعبدني.","10:4":"وإذا أبيت أن تطلق شعبي، فها أنا أجلب غدا الجراد على تخومك،","10:5":"فيغطي وجه الأرض، فيعسر على أحد أن يراها، ويلتهم البقية المتخلفة لكم عن البرد، وكل شجرة نابتة لكم في الحقل،","10:6":"ويملأ بيوتك وبيوت حاشيتك وبيوت جميع المصريين، الأمر الذي لم يشهد مثله آباؤك ولا أجدادك منذ أن استوطنوا هذه الأرض إلى الآن». ثم تحول وانصرف من لدن فرعون.","10:7":"فقالت حاشية فرعون له: «إلى متى يظل هذا الرجل شركا لنا؟ أطلق الشعب ليعبدوا الرب إلههم. ألم تعلم أن مصر قد عمها الخراب؟»","10:8":"فاستدعي موسى وهرون ثانية للمثول أمام فرعون، وقال لهما: «امضوا واعبدوا الرب إلهكم، ولكن من هم الذين سيذهبون؟»","10:9":"فأجاب موسى: «نذهب بفتياننا وشيوخنا. نذهب ببنينا وبناتنا، بمواشينا وقطعاننا لأنه يجب أن نقيم عيدا للرب».","10:10":"فقال فرعون: «ليكن الرب بعونكم إن أنا أطلقتكم مع نسائكم وأولادكم. فمن الجلي أنكم عازمون على الشر.","10:11":"لا، فليمض الرجال فقط لعبادة الرب، لأن هذا هو ما تطلبونه». ثم طردا من حضرة فرعون.","10:12":"فقال الرب لموسى: «ابسط يدك على أرض مصر لتبتلى بالجراد، فيغطي بلاد مصر ويلتهم كل نبات الأرض المتخلف عن البرد».","10:13":"فمد موسى عصاه على أرض مصر، فأرسل الرب عليهم ريحا شرقية طوال ذلك النهار والليل، وما إن أقبل الصباح حتى حملت الريح الشرقية الجراد.","10:14":"فانتشر الجراد في كل بلاد مصر، وحل في جميع تخومها بأسراب عظيمة، فلم يكن له نظير من قبل ولن يحدث مثله فيما بعد.","10:15":"فقد غطى وجه كل الأرض حتى أظلمت، والتهم كل عشب فيها وكل أثمار الأشجار التي خلفها البرد، فلم يبق شيء أخضر لا على الأشجار ولا في حقول المزروعات في كل أرجاء مصر.","10:16":"عندئذ أسرع فرعون فاستدعى موسى وهرون قائلا: «لقد أخطأت إلى الرب إلهكم وإليكما.","10:17":"فاصفحا هذه المرة فقط عن خطيئتي وابتهلا إلى الرب إلهكما كي يزيل عني هذا البلاء المميت».","10:18":"فانصرف موسى من لدن فرعون وابتهل إلى الرب،","10:19":"فأرسل الرب ريحا غربية عاصفة حملت الجراد وطرحته في البحر الأحمر، فلم تبق جرادة واحدة في جميع أرجاء مصر.","10:20":"ولكن الرب صلب قلب فرعون فلم يطلق بني إسرائيل.","10:21":"فقال الرب لموسى: «ابسط يدك نحو السماء فيطغى ظلام على كل أرجاء مصر حتى يكاد يلمس لكثافته».","10:22":"فبسط موسى يده نحو السماء، فطغى ظلام كثيف على كل أرجاء أرض مصر لمدة ثلاثة أيام.","10:23":"فلم يتمكن أحد من أن يرى أخاه، ولا غادر أحد مكانه طوال ثلاثة أيام. غير أن النور كان يغمر بني إسرائيل في أماكن إقامتهم.","10:24":"فاستدعى فرعون موسى وقال: «اذهبوا واعبدوا الرب، ولكن اتركوا وراءكم ماشيتكم وقطعانكم: أما صغاركم فليمضوا معكم أيضا».","10:25":"فقال موسى: «عليك أن تسمح لنا بأخذ ذبائح محرقات لنقدمها للرب إلهنا.","10:26":"لذلك تذهب مواشينا معنا أيضا، فلا يبقى منها ظلف واحد، لأن علينا أن نختار منها لعبادة الرب إلهنا، ولا يمكننا أن نعرف ماذا نختار منها لنعبد الرب حتى نصل إلى هناك».","10:27":"ولكن الرب صلب قلب فرعون فلم يطلق سراحهم.","10:28":"وقال له فرعون: «اذهب عني، واحذر لنفسك. لا تمثل أمامي مرة أخرى، فيوم ترى وجهي تموت».","10:29":"فقال موسى: «حسنا قلت، فأنا لن أرى وجهك مرة أخرى».","11:1":"ثم قال الرب لموسى: «بقيت بلية واحدة أصيب بها فرعون والمصريين، وبعد ذلك يطلقكم من هنا. وعندما يفعل ذلك فإنه يطردكم جميعا طردا.","11:2":"فقل الآن للشعب: ليطلب كل رجل من جاره، وكل امرأة من جارتها، آنية فضة وذهب».","11:3":"ذلك لأن الرب جعل الشعب يحظى برضى المصريين، كما أن الرجل موسى كان عظيما في مصر في عيون حاشية فرعون والشعب.","11:4":"وقال موسى هذا ما يعلنه الرب: «سأجتاز حوالي نصف الليل في وسط مصر،","11:5":"فيموت كل بكر فيها: من بكر فرعون المتربع على العرش إلى بكر الأمة التي وراء الرحى، وكذلك بكر كل بهيمة،","11:6":"فيعلو صراخ عظيم في كل أرض مصر، لم يشهد مثله من قبل ولا يكون مثله أيضا.","11:7":"أما بين الإسرائيليين فلن ينبح كلب على أي إنسان أو حيوان. وعندئذ تعلمون أن الرب يميز بين المصريين وإسرائيل.","11:8":"فيأتي إلي، من ثم، جميع عبيدك هؤلاء وينحنون أمامي قائلين: انطلق أنت وكل من يتبعك من الشعب. وآنئذ فقط أمضي». ثم انصرف من لدن فرعون بغضب محتدم.","11:9":"وقال الرب لموسى: «إن فرعون يأبى الاستماع لكما لكي تتكاثر آياتي في أرض مصر».","11:10":"ولقد أجرى موسى وهرون كل هذه الآيات أمام فرعون، ولكن الرب قسى قلب فرعون فلم يطلق بني إسرائيل من دياره.","12:1":"وخاطب الرب موسى وهرون في أرض مصر قائلا:","12:2":"«منذ الآن يكون لكم هذا الشهر رأس الشهور وأول شهور السنة.","12:3":"خاطبا كل جماعة إسرائيل قائلين: على كل واحد أن يأخذ في العاشر من هذا الشهر حملا لعائلته، وفقا لبيوت الآباء، حملا لكل عائلة.","12:4":"وإن كان البيت صغيرا لا يستهلك حملا كاملا، يتقاسمه هو وجاره القريب منه بحسب عدد الأشخاص الموجودين هناك، بمقدار ما يستطيع كل واحد أن يأكله من الحمل.","12:5":"ويجب أن يكون الحمل ذكرا ابن سنة، خاليا من كل عيب، تنتقونه من الخرفان أو المعيز.","12:6":"ويكون عندكم محفوظا حتى اليوم الرابع عشر من هذا الشهر. ثم يقوم كل جمهور إسرائيل بذبح الحملان عند المساء.","12:7":"ويأخذون الدم ويضعونه على القائمتين والعتبة العليا في البيوت التي يأكلونه فيها.","12:8":"ثم في نفس تلك الليلة يتناولون اللحم مشويا بالنار مع فطير، يأكلونه مع أعشاب مرة.","12:9":"لا تأكلوا منه نيئا أو مسلوقا، بل مشويا بنار، رأسه مع أكارعه وجوفه.","12:10":"ولا تبقوا منه إلى الصباح، بل تحرقون كل ما تبقى منه إلى الصباح بالنار.","12:11":"تأكلونه بعجلة وأحقاؤكم مشدودة، وأحذيتكم في أرجلكم، وعصيكم في أيديكم. فيكون هذا فصحا للرب.","12:12":"ففي هذه الليلة أجتاز في بلاد مصر وأقتل كل بكر فيها من الناس والبهائم وأجري قضاء على كل آلهة المصريين. أنا هو الرب.","12:13":"أما أنتم فإن الدم الذي على بيوتكم المقيمين فيها يكون العلامة التي تميزكم، فأرى الدم وأعبر عنكم، فلا تنزل بكم بلية الهلاك حين أبتلي بها أرض مصر.","12:14":"ويكون لكم هذا اليوم تذكارا تحتفلون به عيدا للرب، فريضة أبدية تحتفلون به في أجيالكم.","12:15":"سبعة أيام تحتفلون، تأكلون فيها فطيرا، تخلون بيوتكم من الخمير في اليوم الأول، فإن كل من أكل خميرا في اليوم الأول إلى اليوم السابع، تباد تلك النفس من إسرائيل.","12:16":"وتقيمون في اليوم الأول حفلا مقدسا، وكذلك في اليوم السابع. لا يجرى فيهما عمل ما إلا تجهيز طعام الأكل. هذا كل ما تعملونه.","12:17":"وتحتفلون بعيد الفطير، لأنني في هذا اليوم عينه أخرجت أجنادكم من أرض مصر، فاحتفلوا بهذا اليوم فريضة أبدية في أجيالكم المقبلة.","12:18":"ومنذ مساء اليوم الرابع عشر من الشهر الأول وحتى مساء اليوم الحادي والعشرين منه تأكلون فطيرا.","12:19":"سبعة أيام تخلو بيوتكم من الخمير فإن كل من أكل خبزا مختمرا يباد من جماعة إسرائيل، الغريب والمواطن على حد سواء.","12:20":"لا تأكلوا شيئا مختمرا، بل في كل مساكنكم تأكلون فطيرا».","12:21":"ثم استدعى موسى كل شيوخ إسرائيل وقال لهم: «اذهبوا وانتقوا حملانا بحسب عائلاتكم واذبحوا حمل الفصح.","12:22":"ثم خذوا باقة زوفا واغمسوها في الدم الذي تصفى في الإناء واطلوا به عتبة الباب العليا والقائمتين، ولا يخرج أحد منكم من بيته حتى الصباح.","12:23":"لأن الرب سيجتاز ليلا ليهلك المصريين. فحين يرى الدم على العتبة العليا والقائمتين يعبر عن الباب ولا يدع المهلك يدخل بيوتكم ليضربكم.","12:24":"فتمارسون هذا الأمر فريضة لكم ولأولادكم إلى الأبد.","12:25":"وعندما تدخلون الأرض التي وعد الرب أن يهبها لكم، فإنكم تمارسون هذه الفريضة.","12:26":"ويكون حين يسألكم أبناؤكم: ماذا تعني هذه الفريضة لكم؟","12:27":"تجيبونهم آنئذ: إنها ذبيحة فصح للرب الذي عبر عن بيوت بني إسرائيل في مصر عندما أهلك المصريين، وأنقذ بيوتنا». فحنى الشعب رؤوسهم ساجدين.","12:28":"فمضى بنو إسرائيل وفعلوا تماما كما أمر الرب موسى وهرون.","12:29":"وفي منتصف الليل أهلك الرب كل بكر في بلاد مصر، من بكر فرعون المتربع على العرش إلى بكر الحبيس في السجن، وأبكار البهائم جميعا أيضا.","12:30":"فاستيقظ فرعون وحاشيته وجميع المصريين وإذا عويل عظيم في أرض مصر، لأنه لم يوجد بيت ليس فيه ميت.","12:31":"فاستدعى موسى وهرون ليلا قائلا: «قوموا واخرجوا من بين الشعب أنتما وبنو إسرائيل، وانطلقوا اعبدوا الرب كما طلبتم،","12:32":"وخذوا معكم غنمكم وبقركم كما سألتم وامضوا وباركوني أيضا».","12:33":"وألح المصريون على الشعب ليسرعوا في الارتحال عن البلاد قائلين: «لئلا نموت جميعا».","12:34":"فصر الشعب في ثيابهم معاجنهم وعجينهم قبل أن يختمر، وحملوها على أكتافهم،","12:35":"وطلبوا من المصريين آنية فضة وذهبا وثيابا بحسب قول موسى.","12:36":"وجعل الرب الشعب يحظى برضى المصريين، فأعطوهم كل ما طلبوه، فغنموا من المصريين.","12:37":"وارتحل بنو إسرائيل من رعمسيس إلى سكوت فكانوا نحو ست مئة ألف من الرجال المشاة ما عدا النساء والأولاد.","12:38":"وكذلك انضم إليهم حشد كبير من الناس، مع غنم ومواش وقطعان كثيرة.","12:39":"ثم خبزوا العجين الذي أخرجوه معهم من مصر خبز ملة، لأنه لم يكن مختمرا، إذ أنهم طردوا من مصر ولم يقدروا أن يتأخروا فما أعدوا لأنفسهم زادا.","12:40":"وكانت مدة غربة بني إسرائيل التي أقاموها في مصر أربع مئة وثلاثين سنة.","12:41":"وفي اليوم الأخير بالذات، في ختام أربع مئة وثلاثين سنة خرج جميع أجناد الرب من أرض مصر.","12:42":"هي ليلة تكرس للرب إذ أخرجهم فيها من أرض مصر. هذه الليلة هي للرب، يكرسها بنو إسرائيل في جميع أجيالهم.","12:43":"وقال الرب لموسى وهرون: «هذه هي مراسيم الفصح: لا يأكل غريب منه.","12:44":"كل عبد مشترى بفضة يأكل منه بعد أن تختنه.","12:45":"النزيل والأجير لا يأكلان منه.","12:46":"يؤكل في بيت واحد فلا تحمل لحما إلى خارج المنزل، ولا تكسر منه عظما.","12:47":"وعلى كل جماعة إسرائيل أن تحتفل به.","12:48":"وإذا عزم غريب مقيم بينكم أن يحتفل بفصح الرب فليختن كل ذكر من أهل بيته، ثم يحتفل به، فيكون آنئذ كمولود الأرض. لا يأكل منه أي ذكر أغلف.","12:49":"فتسود هذه الشريعة على المواطن والدخيل المقيم بينكم».","12:50":"ففعل جميع بني إسرائيل تماما كما أمر الرب موسى وهرون.","12:51":"في ذلك اليوم عينه أخرج الرب بني إسرائيل من أرض مصر بحسب فرق عشائرهم.","13:1":"وقال الرب لموسى:","13:2":"«خصص لي كل بكر ذكر. كل فاتح رحم من بني إسرائيل هو لي. كل بكر من الناس أو البهائم».","13:3":"وقال موسى للشعب: «اذكروا هذا اليوم الذي خرجتم فيه من مصر من بيت العبودية، فقد أطلقكم الرب من هنا بيد قديرة، فلا تأكلوا خبزا مختمرا.","13:4":"اليوم في شهر أبيب (أي في شهر آذار - مارس) أنتم خارجون،","13:5":"لذلك عندما يدخلكم الرب أرض الكنعانيين والحثيين والأموريين والحويين واليبوسيين، التي تفيض لبنا وعسلا، والتي أقسم لآبائكم أن يهبكم إياها، تمارسون هذه الفريضة في هذا الشهر.","13:6":"سبعة أيام لا تأكلون فيها خبزا مختمرا، وفي اليوم السابع يكون احتفال للرب.","13:7":"سبعة أيام تأكلون فيها خبزا فطيرا ولا تحتفظون في بيوتكم بشيء مختمر أو بخمير.","13:8":"في ذلك اليوم تقول لابنك: إنني أمارس هذا من أجل ما صنعه الرب لي، حين أخرجني من مصر.","13:9":"فتكون هذه الفريضة بمثابة علامة على يدك، وتذكارا بين عينيك، لتكون شريعة الرب في فمك، لأن الرب قد أخرجك بيد قديرة من مصر.","13:10":"فتمارس هذه الفريضة في ميعادها مرة كل سنة.","13:11":"ويكون حين يدخلك الرب إلى أرض الكنعانيين، كما أقسم لك ولآبائك أن يهبك إياها،","13:12":"أنك تفرز للرب كل ذكر فاتح رحم. وكذلك كل بكر من نتاج البهائم التي تملكها يكون للرب.","13:13":"إنما كل بكر حمار تفديه بحمل. وإن لم تفده تكسر عنقه. وكذلك تفدي أيضا كل بكر من بنيك.","13:14":"وحين يسألك ابنك في الأيام المقبلة: ما معنى هذا؟ تجيبه: إنه بيد قديرة أخرجنا الرب من ديار العبودية.","13:15":"وعندما تصلب فرعون وامتنع عن إطلاقنا، أهلك الرب كل بكر في بلاد مصر، من أبكار الناس والبهائم. لذلك أنا أقرب للرب الذكور من كل فاتح رحم وأفدي كل بكر من أولادي.","13:16":"فتكون هذه الفريضة بمثابة علامة على يدك ورمزا على جبهتك، لأن الرب قد أخرجنا بيد قديرة من مصر».","13:17":"وعندما أطلق فرعون الشعب لم يقدهم الله في طريق بلاد الفلسطينيين على الرغم من قصرها. لأن الله قال لئلا يندم الشعب إذا تعرض لحرب ويرجع إلى مصر.","13:18":"إنما اقتاد الله الشعب عبر صحراء البحر الأحمر. وكان بنو إسرائيل قد غادروا مصر متسلحين متأهبين للقتال.","13:19":"وحمل موسى عظام يوسف معه، لأنه كان قد استحلف بني إسرائيل بحلف قائلا: «لابد أن يفتقدكم الله فعليكم أن تنقلوا عظامي معكم من هذا المكان».","13:20":"وارتحلوا من سكوت وخيموا في إيثام على طرف الصحراء.","13:21":"وكان الرب يتقدمهم نهارا في عمود سحاب ليهديهم في الطريق، وليلا في عمود نار ليضيء لهم.","13:22":"ولم يبرح عمود السحاب نهارا وعمود النار ليلا من أمام الشعب.","14:1":"وقال الرب لموسى:","14:2":"«قل لبني إسرائيل أن يرجعوا ويتجمعوا مقابل فم الحيروث بين مجدل والبحر أمام بعل صفون مباشرة تخيمون عند البحر،","14:3":"فيظن فرعون أنكم هائمون في الأرض على غير هدى، وقد استغلقت عليكم الصحراء،","14:4":"فأقسي قلب فرعون حتى يسعى وراءكم فأتعظم آنئذ (بالقضاء) على فرعون وعلى جيشه، ويعرف المصريون أني أنا الرب». وهكذا فعل الإسرائيليون.","14:5":"وقيل لملك مصر: «هوذا الشعب قد هرب». فتحول قلب فرعون وقلوب حاشيته ضدهم، وقالوا: «ماذا دهانا حتى أطلقنا إسرائيل من خدمتنا؟»","14:6":"فأعد مركبته واصطحب جيشه معه،","14:7":"فأعد ست مئة مركبة وسائر مركبات مصر، وحمل عليها قادة سلاح المركبات.","14:8":"وقسى الرب قلب فرعون ملك مصر، فطارد بني إسرائيل الذين غادروا مصر بقدرة ظاهرة.","14:9":"وسعى المصريون وراءهم بجميع خيل فرعون ومركباته وفرسانه وجيوشه، فأدركوهم وهم متجمعون عند البحر بالقرب من فم الحيروث مقابل بعل صفون.","14:10":"ولما اقترب فرعون، نظر بنو إسرائيل، وإذا بالمصريين يندفعون نحوهم، فارتعبوا واستغاثوا بالرب،","14:11":"ثم قالوا لموسى: «هل لافتقار مصر للقبور أخرجتنا إلى الصحراء لنموت فيها؟ ماذا فعلت بنا حتى أخرجتنا من مصر؟","14:12":"ألم نقل لك في مصر: دعنا وشأننا فنخدم المصريين، إذ كان خيرا لنا أن نخدم المصريين من أن نموت في الصحراء».","14:13":"فقال موسى للشعب: «لا تخافوا. قفوا وانظروا خلاص الرب الذي يجريه لكم اليوم، لأن المصريين الذين رأيتموهم اليوم، لن تروهم فيما بعد إلى الأبد.","14:14":"فالرب يحارب عنكم وأنتم تصمتون».","14:15":"وقال الرب لموسى: «ما بالك تستغيث بي؟ قل لبني إسرائيل أن يرحلوا.","14:16":"ارفع عصاك وابسط يدك فوق البحر وشقه، فيجتاز بنو إسرائيل في وسط البحر على اليابسة.","14:17":"فها أنا أغلظ قلوب المصريين فيسعون وراءكم، فأتعظم (بالقضاء) على فرعون وعلى مركباته وفرسانه،","14:18":"فيدرك المصريون أنني أنا الرب، عندما أتعظم (بالقضاء) على فرعون ومركباته وفرسانه».","14:19":"وانتقل ملاك الله الذي كان يتقدم عسكر إسرائيل إلى المؤخرة خلفهم، وكذلك انتقل عمود السحاب من أمامهم ووقف وراءهم.","14:20":"فدخل بين عسكر المصريين وعسكر الإسرائيليين، وصار عمود السحاب ظلاما قاتما على المصريين، وضياء على بني إسرائيل، فلم يقترب أحدهما من الآخر طوال الليل.","14:21":"وبسط موسى يده فوق البحر، فأرسل الرب طوال تلك الليلة ريحا شرقية قوية ردت البحر إلى الوراء، وحولته إلى يابسة. وهكذا انشق البحر،","14:22":"فاجتاز الإسرائيليون في وسط البحر على أرض يابسة، فكان الماء بمثابة سورين عن يمينهم وعن يسارهم.","14:23":"ولحق بهم المصريون ودخلوا وراءهم إلى وسط البحر، بجميع خيل فرعون ومركباته وفرسانه.","14:24":"وقبل طلوع الصباح أشرف الرب في عمود النار والسحاب على عسكر المصريين وأربكهم.","14:25":"فجعل عجلات مركباتهم تتخلع. فطفقوا يجرونها بمشقة حتى قال المصريون: «لنهرب من الإسرائيليين، لأن الرب يحارب عنهم ضدنا».","14:26":"وقال الرب لموسى: «ابسط يدك فوق البحر ليرتد الماء على المصريين مع مركباتهم وفرسانهم».","14:27":"فبسط موسى يده فوق البحر عند انبثاق الصباح، فارتد البحر إلى موضعه على المصريين الهاربين في اتجاهه، فجرفهم الرب نحو وسط البحر.","14:28":"وارتدت المياه وأغرقت المركبات والفرسان وكل جيش فرعون الذي لحق بهم إلى البحر، فلم يفلت منهم ناج واحد.","14:29":"أما بنو إسرائيل فقد ساروا فوق أرض يابسة وسط مياه البحر. وكانت المياه كسورين عن يمينهم وعن شمالهم.","14:30":"وهكذا أنقذ الرب في ذلك اليوم الإسرائيليين من يد المصريين، وشاهدوا جثث المصريين مطروحة على شاطئ البحر.","14:31":"وعندما شهد الإسرائيليون القوة العظيمة التي عامل بها الرب المصريين، خاف الشعب الرب وآمنوا به وبموسى عبده.","15:1":"عندئذ شدا موسى وبنو إسرائيل بهذه التسبحة للرب قائلين: «أرنم للرب لأنه تمجد جدا، الفرس وراكبه قد طرحهما في البحر.","15:2":"الرب قوتي ونشيدي وقد صار خلاصي، هذا هو إلهي فأسبحه. وإله أبي فأعظمه.","15:3":"الرب محارب؛ «الرب» اسمه.","15:4":"طرح فرعون وجيشه في البحر، وأغرق خيرة قادة فرعون في البحر الأحمر.","15:5":"غمرتهم اللجج فغاصوا إلى الأعماق كالحجارة.","15:6":"يمينك يا رب مجيدة في قوتها. بيمينك يا رب تسحق العدو.","15:7":"بعظمة جلالك تصرع مقاوميك. ترسل غضبك فتأكلهم كالقش.","15:8":"بريحك العاصفة تكومت المياه، وانتصبت اللجج في قلب البحر.","15:9":"قال العدو: أسعى وراءهم فأدركهم. أقسم أسلابهم وتشتفي منهم نفسي. أستل سيفي بيدي وأهلكهم.","15:10":"لكنك أطلقت ريحك فغشيهم البحر، فغرقوا كالرصاص في اللجج العميقة","15:11":"فمن مثلك يا رب بين كل الآلهة؟ من مثلك جليل في القداسة مهيب في المجد، صانع عجائب!","15:12":"بسطت يمينك فابتلعتهم الأرض.","15:13":"قدت برحمتك الشعب الذي افتديته، وبقدرتك هديته إلى مسكنك المقدس.","15:14":"فتسمع الشعوب وترتعب، وتستولي الرعدة على أهل فلسطين.","15:15":"آنئذ يندهش أمراء أدوم، جبابرة موآب تأخذهم الرجفة، ويذوب حكام كنعان هلعا.","15:16":"يسودهم الخوف والرعدة وبقدرة ذراعك يجمدون كالحجارة حتى يعبر شعبك يا رب، حتى يعبر شعبك الذي اشتريته.","15:17":"تأتي بهم وتغرسهم في جبل ميراثك، الموضع الذي جعلته يا رب لسكناك، المقدس الذي أعدته يا رب يداك.","15:18":"الرب يملك إلى الدهر والأبد».","15:19":"وعندما دخلت خيول فرعون ومركباته وفرسانه إلى البحر رد عليهم مياه البحر، أما بنو إسرائيل فمشوا على اليابسة في وسط البحر.","15:20":"عندئذ أخذت مريم النبية أخت هرون، الدف بيدها، فتبعها جميع النساء بالدف والرقص.","15:21":"فكانت مريم تجاوبهن: «رنموا للرب لأنه قد تمجد جدا. الفرس وراكبه قد طرحهما في البحر».","15:22":"ثم ارتحل موسى بإسرائيل من البحر الأحمر، وتوجهوا نحو صحراء شور، وظلوا يجوبون الصحراء ثلاثة أيام من غير أن يجدوا ماء.","15:23":"وعندما وصلوا إلى مارة لم يقدروا أن يشربوا ماءها لمرارته، لذلك سميت «مارة».","15:24":"فتذمر الشعب على موسى قائلين: «ماذا نشرب؟»","15:25":"فاستغاث بالرب، فأراه الرب شجرة فألقاها إلى الماء، فصار عذبا. وهناك أيضا وضع الرب للشعب فريضة وشريعة، وامتحنه،","15:26":"وقال: «إن كنت تحرص على سماع صوت الرب إلهك، وتفعل ما هو حق أمامه، وتطيع وصاياه وتحافظ على جميع فرائضه، فلن أدعك تقاسي من أي مرض من الأمراض التي ابتليت بها المصريين، فإني أنا الرب شافيك».","15:27":"ثم بلغوا إيليم حيث كانت اثنتا عشرة عين ماء وسبعون نخلة. فخيموا إلى جوار عيون الماء.","16:1":"ثم انتقلت كل جماعة إسرائيل من إيليم حتى أقبلوا إلى صحراء سين الواقعة بين إيليم وسيناء، وذلك في اليوم الخامس عشر من الشهر الثاني بعد خروجهم من أرض مصر.","16:2":"وهناك في الصحراء تذمر بنو إسرائيل على موسى وهرون،","16:3":"وقالوا لهما: «ليت الرب أماتنا في أرض مصر، فهناك كنا نجلس حول قدور اللحم نأكل خبزا حتى الشبع. وها أنتما قد أخرجتمانا إلى هذه الصحراء لتميتا كل هذه الجماعة جوعا».","16:4":"فقال الرب لموسى: «ها أنا أمطر عليكم خبزا من السماء، فيخرج الشعب ويلتقط حاجة كل يوم بيومه، لكي أمتحنهم، فأرى إن كانوا يسلكون في شريعتي أم لا.","16:5":"ولكن ليكن ما يلتقطونه في اليوم السادس ضعف ما يجمعونه في كل يوم».","16:6":"فقال موسى وهرون لجميع بني إسرائيل: «في المساء تعلمون أن الرب هو الذي أخرجكم من أرض مصر.","16:7":"وفي الصباح تعاينون مجد الرب، لأنه قد سمع تذمركم عليه، ولكن من نحن حتى تتذمروا علينا؟»","16:8":"وقال موسى أيضا: «إنكم ستعلمون أنه هو الرب، عندما يعطيكم لحما في المساء لتأكلوا، وخبزا في الصباح لتشبعوا، لأنه سمع تذمركم عليه. فماذا نحن؟ إنكم تتذمرون على الله».","16:9":"وقال موسى لهرون: «قل لبني إسرائيل أن يمثلوا أمام الرب لأنه قد سمع تذمرهم».","16:10":"وفيما كان هرون يخاطب كل جماعة بني إسرائيل، التفتوا نحو الصحراء وإذا بمجد الرب قد تجلى في السحاب.","16:11":"فقال الرب لموسى:","16:12":"«سمعت تذمر بني إسرائيل، فقل لهم: في المساء تأكلون لحما، وفي الصباح تشبعون خبزا، فتعلمون أنني أنا الرب إلهكم».","16:13":"في ذلك المساء أقبلت طيور السلوى (السماني) وغطت المخيم. وفي الصباح كست طبقة الندى الأرض المحيطة بالمخيم.","16:14":"وعندما زالت طبقة الندى إذا وجه الصحراء مغطى بشيء رقيق كالقشور، مكتل كالجليد.","16:15":"وعندما رآه بنو إسرائيل، قال بعضهم لبعض «منهو» أي ما هذا؟ لأنهم لم يعرفوا ما هو. فقال لهم موسى: «هو خبز الرب الذي أعطاكم لتأكلوه.","16:16":"وهذا ما يأمركم به الرب: التقطوا منه كل واحد على قدر مأكله، لكل واحد عمرا (نحو لترين ونصف اللتر) وفقا لعدد أهل بيته المقيمين معه في خيمته».","16:17":"ففعل بنو إسرائيل هكذا فمنهم من التقط مكثرا، ومنهم من التقط مقلا.","16:18":"ولكن عندما كالوا بالعمر ما التقطوه، فإن المكثر لم يفضل عنه، والمقل لم ينقصه شيء، فجمع كل واحد على قدر مأكله.","16:19":"وقال موسى لهم: «لا يبق أحد منه شيئا إلى الصباح».","16:20":"ومع ذلك، فإن بعضهم لم يسمع لموسى، بل أبقوا منه للصباح، فتولد فيه دود وأنتن. فسخط عليهم موسى.","16:21":"فكان كل واحد يلتقط كل صباح على قدر مأكله. وما إن تشتد حرارة الشمس حتى يذوب ما بقي منه على الأرض.","16:22":"أما في اليوم السادس فكانوا يلتقطون من الخبز الضعف، أي عمرين (نحو خمسة لترات) لكل واحد فجاء رؤساء الجماعة وأبلغوا الأمر لموسى.","16:23":"فقال لهم: «هذا ما أمر به الرب. غدا يكون يوم راحة، سبتا مقدسا للرب. اخبزوا ما تريدون خبزه واطبخوا ما تشاؤون، واحتفظوا بما يفضل إلى الصباح».","16:24":"فأبقوه إلى الصباح كما أمر موسى، فلم ينتن ولا صار فيه دود.","16:25":"وقال موسى: «كلوا اليوم لأن اليوم هو سبت للرب، إذ لن تجدوا اليوم طعاما في الحقل.","16:26":"ستة أيام تلتقطونه وأما اليوم السابع فهو سبت ولن تجدوا فيه طعاما».","16:27":"غير أن أناسا منهم خرجوا في السبت ليلتقطوا منه، فلم يجدوا شيئا.","16:28":"ثم قال الرب لموسى: «إلى متى تأبون حفظ وصاياي وشريعتي؟","16:29":"انظروا. فها الرب قد أعطاكم السبت لذلك هو يقدم لكم في اليوم السادس خبز يومين، فليلبث كل واحد في مكانه ولا يغادره في اليوم السابع».","16:30":"فاستراح الشعب في اليوم السابع.","16:31":"ودعا شعب إسرائيل الخبز «منا». وكان أبيض كبزر الكزبرة، ومذاقه كرقاق مصنوعة بعسل.","16:32":"وقال موسى: «إليكم ما أمر به الرب: احفظوا ملء العمر منه ذكرى لأجيالكم المقبلة، لكي يروا الخبز الذي أطعمتكم به في الصحراء عندما أخرجتكم من أرض مصر».","16:33":"وقال موسى لهرون: «خذ إناء واجعل فيه مقدار عمر من المن وضعه أمام الرب ليظل محفوظا في أجيالكم».","16:34":"وكما أمر الرب موسى وضعه هرون أمام الشهادة حفاظا عليه.","16:35":"واقتات الإسرائيليون بالمن طوال أربعين سنة حتى جاءوا إلى تخوم أرض كنعان العامرة بالسكان.","16:36":"وأما العمر فهو عشر الإيفة.","17:1":"وتنقل بنو إسرائيل على مراحل، من صحراء سين بمقتضى أمر الرب إلى أن خيموا في رفيديم حيث لم يجدوا ماء للشرب.","17:2":"فتخاصم الشعب مع موسى قائلين: «أعطونا ماء لنشرب». فأجاب موسى: «لماذا تخاصمونني؟ ولماذا تجربون الرب؟»","17:3":"ولكن الشعب كان ظامئا إلى الماء، فتذمروا على موسى وقالوا: «لماذا أخرجتنا من مصر لتميتنا وأولادنا ومواشينا عطشا؟»","17:4":"فصرخ موسى إلى الرب: «ماذا أصنع بهذا الشعب؟ إنهم يكادون يرجمونني»","17:5":"فأجابه الرب: «تقدم الشعب وخذ معك بعض شيوخ بني إسرائيل، وخذ بيدك عصاك أيضا التي ضربت بها النهر،","17:6":"فها أنا أقف هناك أمامك على الصخرة في حوريب. اضرب الصخرة فينفجر منها الماء ليشرب الشعب». وهكذا فعل موسى أمام شيوخ إسرائيل.","17:7":"ودعا اسم الموضع مسة ومريبة (ومعناه الامتحان والمخاصمة) نتيجة لتخاصم بني إسرائيل وامتحانهم للرب قائلين: «هل الرب في وسطنا أم لا؟»","17:8":"وخرج العمالقة وحاربوا إسرائيل في رفيديم.","17:9":"فقال موسى ليشوع: «انتخب بعض رجالنا وامض لمحاربة عماليق. وها أنا أقف غدا على قمة التل وعصا الله في يدي».","17:10":"فحارب يشوع العمالقة كما أمر موسى. وصعد موسى وهرون وحور على قمة التلة.","17:11":"فطالما كان موسى رافعا يده، يغلب بنو إسرائيل، وإذا خفضها يفوز العمالقة.","17:12":"وعندما دب التعب في يدي موسى أخذ هرون وحور حجرا ووضعاه تحته، فجلس عليه، وأسند هرون وحور يديه، كل واحد منهما من جانب. وهكذا بقيت يداه مرفوعتين حتى مغرب الشمس.","17:13":"فهزم يشوع العمالقة وجيشهم بحد السيف.","17:14":"فقال الرب لموسى: «دون هذا في الكتاب للتذكار، واتله على يشوع، لأنني سأمحو ذكر العمالقة من تحت السماء».","17:15":"وشيد موسى مذبحا للرب دعاه «يهوه نسي» (ومعناه: الرب رايتي أو علمي)،","17:16":"قائلا: «لأن يدا ارتفعت ضد عرش الرب، فإن الرب سيحارب العمالقة جيلا بعد جيل».","18:1":"وسمع يثرون كاهن مديان وحمو موسى بجميع ما أجراه الله لموسى ولإسرائيل شعبه، وكيف أخرجهم من مصر،","18:2":"فأخذ يثرون حمو موسى صفورة زوجة موسى التي كان قد أرجعها إلى أبيها","18:3":"وابنيها اللذين يدعى أحدهما جرشوم (ومعناه: غريب) لأن (موسى) قال: «كنت نزيلا في أرض غريبة».","18:4":"واسم الثاني أليعازر (ومعناه: إلهي عون لي) لأنه قال: «إله أبي كان عوني، فأنقذني من سيف فرعون».","18:5":"وقدم يثرون حمو موسى ومعه ابنا موسى وزوجته إلى موسى في الصحراء حيث كان مجتمعا عند جبل الله.","18:6":"فأرسل إلى موسى قائلا: «أنا حموك يثرون قادم إليك ومعي زوجتك وابناها».","18:7":"فخف موسى لاستقبال حميه، وانحنى له احتراما وقبله. وسأل كل منهما الآخر عن أحواله، ثم دخلا إلى الخيمة.","18:8":"وسرد موسى على حميه كل ما أجراه الرب على فرعون والمصريين لإنقاذ بني إسرائيل، وما تعرضوا له من مشقة في الطريق، وكيف أنقذهم الرب منها.","18:9":"فاغتبط يثرون بجميع ما صنعه الرب من إحسان إلى إسرائيل، إذ أنقذهم من يد المصريين.","18:10":"وقال يثرون: «مبارك الرب الذي أنقذكم من يد المصريين ومن يد فرعون، وحرر الشعب من نير المصريين.","18:11":"الآن أعلم أن الرب هو أعظم من جميع الآلهة، لأنه عاملهم بمثل ما بغوا به».","18:12":"وقدم يثرون حمو موسى محرقة وذبائح لله. وجاء هرون وجميع شيوخ إسرائيل ليأكلوا طعاما مع حمي موسى في حضرة الله.","18:13":"وفي الصباح جلس موسى ليقضي للشعب، وظل الشعب واقفا لدى موسى من الصباح إلى المساء.","18:14":"فلما رأى حمو موسى جميع ما يقوم به للشعب قال له: «ما هذا الذي تصنعه للشعب؟ ولماذا تجلس وحدك للقضاء، بينما يظل جميع الشعب واقفا لديك من الصباح إلى المساء؟»","18:15":"فأجاب موسى: «لأن الشعب يقبل إلي ليستطلع إرادة الله.","18:16":"فإن كان لهم دعوى يلجأون إلي فأقضي بين الرجل والآخر، وأطلعهم على فرائض الله وشرائعه».","18:17":"فقال حمو موسى: «إن ما تفعله ليس بالأمر الصائب،","18:18":"إذ لابد للكلل أن يعتريك أنت وكل هذا الشعب الذي معك، لأن الأمر فوق طاقتك، ولا يمكنك أن تتولاه وحدك.","18:19":"فأصغ إلى صوتي لأسدي لك نصيحة، وليكن الله معك. فلتكن أنت ممثل الشعب أمام الله، فترفع إليه دعاواهم.","18:20":"وعلمهم الفرائض والشرائع، وأعلن لهم الطريق الذي يسلكونه، وما يستوجب عليهم القيام به من أعمال.","18:21":"ولكن اختر من بين الشعب رجالا مقتدرين خائفين الله أمناء يبغضون الرشوة، تقيمهم عليهم رؤساء لفئات الألوف والمئات والخماسين والعشرات.","18:22":"فيقضون للشعب في الدعاوى الصغيرة في كل حين. أما القضايا المستعصية فيرفعونها إليك، فيخفف ذلك عنك، إذ يشاركونك في حمل العبء.","18:23":"فإن فعلت هذا وأوصاك الله به، أمكنك القيام بمسؤولياتك، ويمضي جميع هذا الشعب إلى مكانه بسلام».","18:24":"فاستمع موسى إلى نصيحة حميه، ونفذ كل ما قاله له،","18:25":"واختار موسى من بين جميع الإسرائيليين رجالا مقتدرين، وأقامهم على الشعب، رؤساء ألوف ومئات وخماسين وعشرات.","18:26":"فكانوا يقضون للشعب في كل الدعاوى الصغيرة. أما القضايا المستعصية فكانوا يرفعونها إلى موسى.","18:27":"ثم شيع موسى حماه، فرجع هذا إلى أرضه.","19:1":"وفي تمام الشهر الثالث من خروج بني إسرائيل من أرض مصر وصلوا إلى برية سيناء.","19:2":"فقد ارتحل الإسرائيليون من رفيديم إلى أن جاءوا إلى برية سيناء، فنزلوا مقابل الجبل.","19:3":"فصعد موسى للمثول أمام الله. فناداه الرب من الجبل: «هكذا تقول لآل يعقوب، وتخبر شعب إسرائيل:","19:4":"لقد عاينتم بأنفسكم ما أجريته على مصر، وكيف حملتكم على أجنحة النسور وجئت بكم إلي.","19:5":"لذلك إن أطعتم عهدي، تكونوا لي ملكا خاصا من بين جميع الشعوب، لأن لي كل الأرض.","19:6":"وتكونوا لي مملكة كهنة وأمة مقدسة. هذا هو الكلام الذي تخاطب به بني إسرائيل».","19:7":"فاستدعى موسى شيوخ الشعب وتلا أمامهم جميع هذا الكلام الذي أوصاه به الرب.","19:8":"فقال كل الشعب معا: «كل ما نطق به الرب نعمل». فحمل موسى جوابهم إلى الرب.","19:9":"فقال الرب لموسى: «ها أنا مقبل عليك في هيئة سحاب مظلم، فيسمعني الشعب حينما أخاطبك، فيثقون أيضا بك دائما». ونقل موسى إلى الرب كلام الشعب.","19:10":"وقال الرب لموسى: «انزل إلى الشعب وقدسهم اليوم وغدا، ودعهم يغسلون ثيابهم،","19:11":"ليكونوا متأهبين لليوم الثالث، لأنه في اليوم الثالث أنزل أمام جميع الشعب على جبل سيناء.","19:12":"وأقم حدودا حول الجبل لا يتخطاها الشعب. وقل لهم: حذار من أن تصعدوا إلى الجبل، أو تمسوا طرفه، فكل من يمس الجبل حتما يقتل.","19:13":"لا تمسه يد، بل يرجم رجما أو يرمى بالسهام، سواء أكان بهيمة أم إنسانا. لا يبقى عليه. أما عندما يتردد صوت بوق طويل، فعندئذ فقط يصعدون إلى الجبل».","19:14":"وبعد أن انحدر موسى من الجبل إلى الشعب قدسهم وغسلوا ثيابهم،","19:15":"وقال للشعب: «كونوا متأهبين لليوم الثالث، وامتنعوا عن معاشرة نسائكم».","19:16":"وفي صباح اليوم الثالث حدثت رعود وبروق، وخيم سحاب كثيف على الجبل، ودوى صوت بوق قوي جدا، فارتعد كل الشعب الذي في المخيم،","19:17":"فأخرج موسى الشعب من المخيم للقاء الله، فوقفوا عند سفح الجبل.","19:18":"وكان جبل سيناء كله مغطى بدخان، لأن الرب نزل عليه في هيئة نار. وتصاعد دخانه كدخان الأتون، واهتز الجبل كله بعنف.","19:19":"وازداد دوي البوق أكثر فيما كان موسى يتكلم، والرب يجيبه برعد.","19:20":"ونزل الرب على قمة جبل سيناء، ونادى موسى ليصعد إلى قمة الجبل، فصعد إليه.","19:21":"فقال له الرب: «انزل وحذر الشعب لئلا يقتحموا الجبل ليروني فيهلك منهم كثيرون.","19:22":"وليتقدس أيضا الكهنة الذين يقتربون إلي لئلا أبطش بهم».","19:23":"فقال موسى للرب: «لا يقدر الشعب أن يصعد إلى جبل سيناء، لأنك أنت قد حذرتنا قائلا: أقم حدودا حول الجبل وقدسه».","19:24":"فأجاب الرب: «انزل واصعد بأخيك هرون معك، أما الكهنة والشعب فلا يقتحموا طريقهم ليصعدوا إلي لئلا أبطش بهم».","19:25":"فانحدر موسى إلى الشعب وأنذرهم.","20:1":"ثم نطق الله بجميع هذه الأقوال:","20:2":"«أنا هو الرب إلهك الذي أخرجك من أرض مصر ديار عبوديتك.","20:3":"لا يكن لك آلهة أخرى سواي.","20:4":"لا تنحت لك تمثالا، ولا تصنع صورة ما مما في السماء من فوق، وما في الأرض من تحت، وما في الماء من أسفل الأرض.","20:5":"لا تسجد لهن ولا تعبدهن، لأني أنا الرب إلهك، إله غيور، أفتقد آثام الآباء في البنين حتى الجيل الثالث والرابع من مبغضي،","20:6":"وأبدي إحسانا نحو ألوف من محبي الذين يطيعون وصاياي.","20:7":"لا تنطق باسم الرب إلهك باطلا، لأن الرب يعاقب من نطق باسمه باطلا.","20:8":"اذكر يوم السبت لتقدسه،","20:9":"ستة أيام تعمل وتقوم بجميع مشاغلك،","20:10":"أما اليوم السابع فتجعله سبتا للرب إلهك، فلا تقم فيه بأي عمل أنت أو ابنك أو ابنتك أو عبدك أو أمتك أو بهيمتك أو النزيل المقيم داخل أبوابك.","20:11":"لأن الرب قد صنع السماء والأرض والبحر وكل ما فيها في ستة أيام، ثم استراح في اليوم السابع. لهذا بارك الرب يوم السبت وجعله مقدسا.","20:12":"أكرم أباك وأمك لكي يطول عمرك في الأرض التي يهبك إياها الرب إلهك.","20:13":"لا تقتل.","20:14":"لا تزن.","20:15":"لا تسرق.","20:16":"لا تشهد زورا على جارك.","20:17":"لا تشته بيت جارك، ولا زوجته، ولا عبده، ولا أمته، ولا ثوره، ولا حماره، ولا شيئا مما له».","20:18":"وعندما عاين الشعب كله الرعود والبروق، وسمعوا دوي صوت البوق، ورأوا الجبل يدخن ارتجفوا خوفا ووقفوا من بعيد،","20:19":"وقالوا لموسى: «كلمنا أنت بنفسك فنسمع، لئلا نموت إذا ظل الله يخاطبنا».","20:20":"فأجاب موسى: «لا تخافوا. إنما الرب قد جاء ليمتحنكم حتى تظل مخافة الرب تلازمكم فلا تخطئوا».","20:21":"وبينما كان الشعب واقفا من بعيد، اقترب موسى من الظلام المتكاثف حيث كان الله.","20:22":"فقال الرب لموسى: «تقول لبني إسرائيل: أنتم رأيتم بأنفسكم كيف كلمتكم من السماء.","20:23":"فامتنعوا عن صنع آلهة فضة أو آلهة ذهب لكم لتشركوها معي.","20:24":"أقم لي مذبحا من تراب تقدم عليه محرقاتك وقرابين سلامتك من غنمك وبقرك. وآتي إليك وأباركك في جميع الأماكن التي أقيم فيها لاسمي ذكرا.","20:25":"وإن بنيت لي مذبحا من حجارة، فلا تبنه من حجارة منحوتة، لأن استعمالك للإزميل يدنسها","20:26":"ولا ترتق إلى مذبحي بدرج لئلا تنكشف عورتك عليه».","21:1":"وهذه هي الأحكام التي تضعها أمامهم:","21:2":"إن اشتريت عبدا عبرانيا فليخدمك ست سنوات، وفي السنة السابعة تطلقه حرا مجانا","21:3":"وإذا اشتريته وهو أعزب يطلق وحده. وإن اشتريته وهو بعل امرأة، تطلق زوجته معه.","21:4":"وإن وهبه مولاه زوجة وأنجبت له بنين وبنات، فإن زوجته وأولادها يكونون ملكا لسيده، وهو يطلق وحده حرا.","21:5":"لكن إن قال العبد: «أحب مولاي وزوجتي وأولادي، ولا أريد أن أخرج حرا.","21:6":"يأخذه سيده إلى قضاة المدينة، ثم يقيمه لصق الباب أو قائمته، ويثقب أذنه بمخرز، فيصبح خادما له مدى الحياة.","21:7":"ولكن إذا باع رجل ابنته كأمة، فإنها لا تطلق حرة كما يطلق العبد.","21:8":"فإذا لم ترق لمولاها الذي خطبها لنفسه، يسمح بافتدائها، ولا يحق له أن يبيعها لقوم أجانب لأنه غدر بها فلم يتزوجها","21:9":"وإن خطبها لابنه فإنه يعاملها كابنة له.","21:10":"أما إذا أعجبته وتزوجها، ثم عاد فتزوج من أخرى، فإنه لا ينقص شيئا من طعامها وكسوتها ومعاشرتها،","21:11":"فإذا قصر في واحد من هذه الأشياء الثلاثة، عليه أن يطلقها حرة مجانا.","21:12":"من ضرب إنسانا وقتله، فالضارب حتما يموت.","21:13":"ولكن إن لم يتعمد الضارب ذلك، بل حدث الأمر بقضاء الله فإني سأعين له مكانا يلجأ إليه.","21:14":"ولكن إذا تآمر أحد على آخر وتعمد قتله، فسقه للموت حتى ولو احتمى بمذبحي","21:15":"كل من يضرب أباه أو أمه، يقتل.","21:16":"من يخطف إنسانا ويبعه أو يسترقه عنده حتما يمت.","21:17":"من يشتم أباه أو أمه يقتل.","21:18":"إذا تعارك رجلان فضرب أحدهما الآخر بحجر أو لكمه من غير أن يميته بل ألزمه الفراش،","21:19":"ثم قام متمشيا متوكئا على عكازه، يبرأ الضارب، إلا أن عليه أن يدفع للمضروب تعويضا عن مدة تعطله، ويتحمل نفقات علاجه.","21:20":"إن ضرب أحد عبده أو أمته بالعصا ضربا أفضى إلى الموت، يعاقب.","21:21":"لكن إن بقي حيا يوما أو يومين، لا يعاقب الضارب، لأن العبد ملكه.","21:22":"إن تضارب رجال وصدموا امرأة حاملا فأجهضت من غير أن تتأذى، يدفع الصادم غرامة بمقتضى ما يطالب به الزوج ووفقا لقرار القضاة.","21:23":"أما إذا تأذت المرأة، تأخذ نفسا بنفس،","21:24":"وعينا بعين، وسنا بسن، ويدا بيد، ورجلا برجل،","21:25":"وكيا بكي، وجرحا بجرح، ورضا برض.","21:26":"وإذا ضرب أحد عبده أو أمته، فأتلف عينه، فإنه يطلقه حرا تعويضا له عن عينه","21:27":"وإذا ضرب أحد عبده أو أمته، فأسقط سنه، فإنه يطلقه حرا تعويضا عن سنه.","21:28":"إذا نطح ثور رجلا أو امرأة فمات، يرجم الثور حتى الموت ولا تأكلون لحمه، ويكون صاحب الثور بريئا.","21:29":"أما إن كان الثور نطاحا من قبل، وسبق إنذار صاحبه، فلم يكبحه، فقتل رجلا أو امرأة، يرجم الثور، ويقتل صاحبه.","21:30":"إلا إذا طولب بدفع الدية، فيدفع آنئذ فداء نفسه ما هو متوجب عليه.","21:31":"وإذا نطح ابنا أو ابنة، ينفذ فيه هذا الحكم.","21:32":"وإذا نطح الثور عبدا أو أمة، فإن صاحبه يدفع ثلاثين قطعة فضة تعويضا لمولاه، ويرجم الثور.","21:33":"إن كشف إنسان غطاء بئره، أو حفر بئرا وتركها من غير غطاء، فوقع فيها ثور أو حمار،","21:34":"يقوم صاحب البئر بدفع تعويض عن الخسارة تضاهي ثمنه، ويكون الميت له.","21:35":"وإذا نطح ثور إنسان ثور صاحب له فمات الثور، فإنهما يبيعان الثور الحي ويقتسمان ثمنه، وكذلك يقتسمان الثور الميت.","21:36":"وأما إذا كان معروفا من قبل، أن الثور نطاح ولم يكبحه صاحبه، فإنه يعوض ثورا بثور، ويكون الثور الميت له.","22:1":"وإذا سرق إنسان ثورا أو خروفا وذبحه أو باعه، فعليه أن يعوض صاحب الثور بخمسة ثيران، وصاحب الخروف بأربعة من الغنم.","22:2":"إذا ضبط السارق وهو ينقب ليلا وضرب فمات، يذهب دمه هدرا.","22:3":"ولكن إن ضبط بعد شروق الشمس وهو ينقب وضرب حتى قتل، يكون الضارب مطالبا بدمه. على اللص أن يدفع تعويضا. إن كان معدما، يباع بسرقته.","22:4":"وإذا وجد الحيوان المسروق حيا في حوزته، ثورا كان أم حمارا أم خروفا، يعوض السارق بمثلين.","22:5":"إذا سرح إنسان بهائمه لترعى في حقل جاره أو كرمه، فعليه أن يعوض صاحب الحقل أو الكرم من أجود نتاج حقله أو كرمه.","22:6":"إذا اندلعت نار وامتدت من الشوك إلى أكداس القمح أو السنابل النامية أو مزروعات الحقول، فعلى من أوقد النار أن يعوض الخسارة.","22:7":"إذا أودع إنسان صاحبه فضة أو أمتعة أمانة، ثم سرقت من بيت صاحبه، فعلى السارق إذا اكتشف أمره أن يدفع ضعفي قيمة المسروق كتعويض.","22:8":"ولكن إذا لم يقبض على اللص، يمثل صاحب البيت أمام القضاة ليقر روا إن كان هو الذي امتدت يده إلى أمتعة صاحبه.","22:9":"في كل قضية حيازة غير شرعية سواء أكانت متعلقة بثوب أم حمار أم خروف أم ثور أم أي شيء مفقود، يدعي شخص ما أنه يملكه، يمثل الطرفان المتنازعان أمام القضاة، ومن يحكم عليه القضاة بالذنب يعوض صاحبه بمثلين.","22:10":"إذا أودع إنسان ثورا أو حمارا أو بهيمة أمانة، فمات أو تأذى أو سرق في غفلة.","22:11":"يحلف صاحب البيت بالرب أنه لم يمد يده إلى ملك جاره، فيقبل منه صاحبه اليمين ولا يأخذ تعويضا.","22:12":"ولكن إن سرق منه بفعل الإهمال فعليه أن يعوض صاحبه.","22:13":"أما إذا افترس فعليه أن يأتي بأشلائه شهادة على ذلك، ولا يطالب بالتعويض عن الحيوان المفترس.","22:14":"إذا استعار إنسان من صاحبه شيئا فانكسر أو مات في غياب صاحبه، يدفع المستعير تعويضا.","22:15":"لكن إن كان صاحب الحيوان حاضرا، فلا يدفع المستعير تعويضا. أما إذا كان الحيوان أو الشيء مستأجرا، فتغطي الأجرة المدفوعة قيمة الخسارة.","22:16":"إذا راود رجل عذراء غير مخطوبة، وعاشرها، يدفع مهرها ويتزوجها،","22:17":"وإن أبى والدها قطعيا أن يزوجها منه، يتحتم عليه أيضا أن يدفع له مهر العذارى.","22:18":"لا تدع ساحرة تعيش.","22:19":"كل من ضاجع بهيمة حتما يقتل.","22:20":"من يقرب ذبائح لآلهة غير الرب وحده، يبد.","22:21":"لا تضطهد غريبا ولا تضايقه، فقد كنتم غرباء في ديار مصر.","22:22":"لا تسئ إلى أرملة أو يتيم،","22:23":"لأنك إن أسأت إليهما وصرخا إلي أسمع صراخهما،","22:24":"فيحتدم غضبي وأقتلكم بالسيف، فتصبح زوجاتكم أرامل وأولادكم يتامى.","22:25":"إن أقرضت فقيرا من شعبي المقيم عندك فلا تعامله كالمرابي، ولا تتقاض منه فائدة.","22:26":"إذا استرهنت ثوب صاحبك لقاء دين، فرده إليه عند مغيب الشمس،","22:27":"لأن ذلك الثوب هو ثوبه الذي يقي به بدنه، وإلا فبأي شيء ينام؟ إذا صرخ إلي أسمعه لأني رحيم.","22:28":"لا تشتم القضاة ولا تلعن رؤساء شعبك.","22:29":"لا تؤخر تقديم باكورة محصول بيدرك ومعصرتك، وأعطني أبكار بنيك.","22:30":"وكذلك تفعل ببقرك وغنمك. سبعة أيام تبقي البكر مع أمه، وفي يومه الثامن تقدمه لي.","22:31":"وتكونون لي شعبا مقدسا. لا تأكلوا لحم فريسة في الصحراء، بل اطرحوه طعاما للكلاب.","23:1":"لا تنقل أخبارا كاذبة، ولا تتعاون مع المنافق في شهادة زور.","23:2":"لا تتبع لأغلبية لارتكاب الشر، ولا تحرف شهادتك في دعوى انجرافا مع الأكثرية،","23:3":"ولا تتحيز للفقير في دعواه لمجرد كونه فقيرا فقط.","23:4":"إذا صادفت ثور عدوك أو حماره شاردا، فرده إليه.","23:5":"وإذا عاينت حمار مبغضك واقعا تحت حمله، فلا تتجاوزه حتى تسعف عدوك في حل ثقل حماره.","23:6":"لا تتهاون في حق فقيرك في دعواه لكونه فقيرا.","23:7":"اجتنب الاتهام الكاذب ولا تقتل البريء والصالح، لأنني لا أبرىء المذنب.","23:8":"لا تقبل رشوة لأن الرشوة تعمي المبصرين وتحرف أقوال الصالحين.","23:9":"لا تضايق غريبا لأنكم تعلمون مشاعر الغريب، فقد كنتم غرباء في ديار مصر.","23:10":"ازرع أرضك واحصد غلتها ست سنين،","23:11":"ثم أرحها في السنة السابعة واتركها ليأكل منها فقراء شعبك. وما فضل عنهم تقتاته وحوش البرية. وهكذا تفعل أيضا بكرمك وزيتونك.","23:12":"اعمل ستة أيام فقط، وفي اليوم السابع تستريح لكي يستريح أيضا ثورك وحمارك، وينتعش ابن أمتك والغريب.","23:13":"أطيعوا كل ما أوصيتكم به، ولا تذكروا اسم آلهة أخرى، ولا يتلفظ به فمك.","23:14":"ثلاث مرات تحتفل لي في السنة:","23:15":"تحتفل بعيد الفطير فتأكل كما أمرتك فطيرا، مدة سبعة أيام، في الوقت المعين من شهر أبيب (أي شهر آذار - مارس)، لأنه فيه خرجت من مصر. ولا يمثل أحد أمامي بيدين فارغتين.","23:16":"وتحتفل أيضا بعيد الحصاد، حيث تقدم باكورة غلاتك التي زرعتها في الحقل، ثم عيد الجمع في نهاية موسم الحصاد عندما تجمع غلاتك من الحقل.","23:17":"ثلاث مرات يمثل جميع الرجال أمام السيد الرب.","23:18":"لا تقرب لي دم ذبيحة مع خبز مختمر، ولا يبت شحم ذبائح عيدي إلى صباح الغد.","23:19":"أحضر أجود باكورة أرضك إلى بيت إلهك. ولا تطبخ جديا في لبن أمه.","23:20":"ها أنا مرسل ملاكي أمامك ليحرسك طوال الطريق، ويقودك إلى الأرض التي أعددتها لك.","23:21":"فأصغ إليه وامتثل له ولا تعصه لأنه لا يصفح عن ذنوبكم إذ أن اسمي فيه.","23:22":"إن حرصت على الاستماع إلى أقواله وفعلت كل ما قلته، أعادي من يعاديك، وأقاوم مقاوميك،","23:23":"إذ يسير ملاكي أمامك حتى يدخلك بلاد الأموريين والحثيين والفرزيين والكنعانيين والحويين واليبوسيين الذين أبيدهم.","23:24":"إياك أن تسجد لآلهتهم، ولا تعبدها، ولا تعمل أعمالهم، بل تبيدهم وتحطم أصنامهم.","23:25":"إنما تعبدونني أنا الرب إلهكم فأبارك طعامك وشرابك وأزيل الأمراض من بينكم","23:26":"فلا تكون مجهضة ولا عاقر في أرضك. وأمتعك بكامل عمرك.","23:27":"وأجعل هيبتي تتقدمك، أزعج كل أمة تقف في وجهك، وأجعل أعداءك يولون الأدبار أمامك.","23:28":"وأبعث الزنابير أمامك، فتطرد الحويين والكنعانيين والحثيين من قدامك.","23:29":"إنما لن أطردهم في سنة واحدة لئلا تقفر الأرض فتتكاثر عليك وحوش البرية،","23:30":"بل أطردهم تدريجيا من أمامك ريثما تنمون وترثون البلاد.","23:31":"وأجعل تخومك تمتد من البحر الأحمر إلى ساحل فلسطين، ومن البرية حتى نهر الفرات، وأخضع لك سكان الأرض فتطردهم من أمامك.","23:32":"لا تقطع معهم ولا مع آلهتهم عهدا،","23:33":"ولا تسكنهم في أرضك لئلا يجعلوك تخطئ إلي، لأنك إن عبدت آلهتهم، يكون ذلك لك فخا».","24:1":"ثم قال الرب لموسى: «اصعد إلي أنت وهرون وناداب وأبيهو، وسبعون من شيوخ إسرائيل وليسجد هؤلاء من بعيد.","24:2":"لا يقترب إلي أحد سواك، أما الآخرون فيبقون بعيدا. وحذار أن يصعد الشعب معك».","24:3":"فجاء موسى وبلغ الشعب بكل كلام الرب وأحكامه، فأجاب الشعب بصوت واحد: «كل ما أمرنا به الرب نفعل».","24:4":"فكتب موسى جميع أقوال الرب، ثم بكر في الصباح وشيد مذبحا على سفح الجبل، ونصب اثني عشر عمودا على عدد أسباط بني إسرائيل الاثني عشر.","24:5":"وأرسل بعض شبان بني إسرائيل فقدموا محرقات وقربوا ذبائح سلامة للرب من العجول،","24:6":"وأخذ موسى نصف الدم واحتفظ به في طسوس ورش النصف الباقي على المذبح.","24:7":"وتناول كتاب العهد وتلاه على مسامع الشعب، فقالوا: «كل ما أمر به الرب نفعله ونطيعه».","24:8":"ثم أخذ موسى الدم الذي في الطسوس ورشه على الشعب قائلا: «هوذا دم العهد الذي قطعه الرب معكم بناء على جميع هذه الأقوال».","24:9":"ثم صعد موسى وهرون وناداب وأبيهو وسبعون من شيوخ إسرائيل،","24:10":"ورأوا إله إسرائيل، وتحت قدميه أرضية كأنها مصنوعة من الياقوت الأزرق الشفاف تماثل السماء في النقاء،","24:11":"ولكن الله لم يمد يده ليهلك أشراف بني إسرائيل، فرأوا الله وأكلوا وشربوا.","24:12":"وقال الرب لموسى: «اصعد إلى الجبل وامكث هناك لأعطيك الوصايا والشرائع التي كتبتها على لوحي الحجر لتلقنها لهم».","24:13":"فقام موسى وأخذ خادمه يشوع وصعد إلى جبل الله.","24:14":"وقال للشيوخ: «انتظرونا هنا حتى نرجع إليكم. وهوذا هرون وحور معكم، فإن كان لأحد دعوى فليرفعها إليهما».","24:15":"وعندما صعد موسى إلى الجبل، تغطى الجبل بالسحاب،","24:16":"وحل مجد الرب على جبل سيناء، وغطاه السحاب ستة أيام. وفي اليوم السابع دعا الرب موسى من وسط السحاب.","24:17":"وبدا مجد الرب لعيون بني إسرائيل كنار آكلة على قمة الجبل.","24:18":"واختفى موسى في وسط السحاب وصعد إلى الجبل حيث مكث هناك أربعين نهارا وأربعين ليلة.","25:1":"وخاطب الرب موسى:","25:2":"«كلم بني إسرائيل أن يأخذوا لي تقدمة من كل إنسان يحثه قلبه على ذلك.","25:3":"أما التقدمات التي تأخذونها منهم فهي: ذهب وفضة ونحاس","25:4":"وأقمشة زرقاء وبنفسجية وحمراء، ومنسوجات كتانية وشعر معزى،","25:5":"وجلود كباش مصبغة بالحمرة، وجلود دلافين وخشب السنط،","25:6":"وزيت للمنارة، وأطياب لدهن المسحة وللبخور العطر","25:7":"وحجارة جزع كريمة وحجارة كريمة أخرى لترصيع رداء الكاهن وصدرته.","25:8":"فيصنعون لي مقدسا حيث أقيم فيه بينهم.","25:9":"تصنعونه حسب مثال المسكن والآنية التي أريك.","25:10":"يصنعون تابوتا من خشب السنط، طوله ذراعان ونصف (نحو متر وربع المتر)، وعرضه ذراع ونصف (نحو خمسة وسبعين سنتيمترا) وارتفاعه ذراع ونصف (نحو خمسة وسبعين سنتيمترا).","25:11":"وتضع عليه غشاء من ذهب نقي من الداخل والخارج، واجعل له إطارا من ذهب،","25:12":"واسبك له أربع حلقات من ذهب تثبتها على قوائمه الأربع حلقتين من كل جانب،","25:13":"وتصنع عصوين من خشب السنط تغشيهما بالذهب،","25:14":"ثم تدخلهما في الحلقات التي على جانبي التابوت ليحمل بهما.","25:15":"وتبقى العصوان في حلقات التابوت، لا تنزعان منها.","25:16":"ثم تضع الشهادة التي أعطيك في داخل التابوت.","25:17":"وتصنع غطاء من ذهب خالص، هو كرسي الرحمة، طوله ذراعان ونصف (نحو متر وربع المتر) وعرضه ذراع ونصف (نحو خمسة وسبعين سنتيمترا)","25:18":"وتخرط كروبين (تمثالي ملاكين) من ذهب وتقيمهما على طرفي الغطاء.","25:19":"فتصنع كروبا واحدا على كل طرف من الغطاء، مخروطين من الغطاء نفسه، وقائمين على طرفيه.","25:20":"ويكون الكروبان متواجهين أيضا، باسطين أجنحتهما إلى فوق، يظللان بهما الغطاء، ويتجهان بوجهيهما نحوه.","25:21":"وتضع الغطاء فوق التابوت الذي تحتفظ بداخله بلوحي الشهادة التي أعطيك.","25:22":"وهناك أجتمع بك وأكلمك بكل ما أوصيك به لتبلغه لبني إسرائيل من على الغطاء، ما بين الكروبين اللذين يعلوان تابوت الشهادة.","25:23":"وكذلك تصنع مائدة من خشب السنط طولها ذراعان (نحو متر) وعرضها ذراع (نحو خمسين سنتيمترا) وارتفاعها ذراع ونصف (نحو خمسة وسبعين سنتيمترا)","25:24":"وغشها بالذهب واصنع لها إطارا عاليا من الذهب،","25:25":"واصنع لها حافة حولها مقدار عرضها شبر، واجعل لمحيط الحافة إطارا من ذهب،","25:26":"واسبك لها أربع حلقات من ذهب تثبتها على زوايا قوائمها الأربع،","25:27":"فتكون الحلقات المثبتة على الحافة، أماكن لعصوين تحمل بهما المائدة.","25:28":"وتصنع العصوين من خشب السنط وتغشيهما بالذهب لتحمل بهما المائدة.","25:29":"وأما صحاف المائدة وصحونها وكؤوسها وأباريقها التي يسكب بها، فتصوغها من ذهب خالص.","25:30":"وتضع أمامي «خبز التقدمة» على هذه المائدة دائما.","25:31":"واخرط منارة من ذهب خالص، فتكون قاعدتها وساقها وكاساتها وبراعمها وأزهارها كلها مخروطة معا من قطعة واحدة.","25:32":"وتتشعب من كل جانب منها ثلاثة أفرع،","25:33":"في كل شعبة ثلاث كاسات ببرعم وزهر، وهكذا إلى الستة الأفرع المتشعبة من المنارة.","25:34":"ويكون على المنارة أربع كاسات لوزية الشكل ببراعمها وأزهارها.","25:35":"وتجعل تحت فرعين من الأفرع المتشعبة من المنارة برعما. هكذا تفعل للستة أفرع.","25:36":"ويكون ساق المنارة وبراعمها وأفرعها كلها قطعة واحدة مصوغة من ذهب خالص.","25:37":"ثم اصنع سبعة سرج للمنارة، واجعلها عليها بحيث تضيء أمامها.","25:38":"ولتكن ملاقطها ومنافضها من ذهب خالص.","25:39":"فيكون وزن الذهب الخالص المصاغ لصنع المنارة وجميع أوانيها وزنة واحدة (نحو ستة وثلاثين كيلو جراما)","25:40":"واحرص أن يكون كل ما تصنعه مطابقا للمثال الذي أظهرته لك على الجبل.","26:1":"أما المسكن فتصنع سقفه من عشر قطع كتانية مبرومة بإتقان، ذات ألوان زرقاء وبنفسجية وحمراء طرز عليها حائك ماهر (رسم) الكروبيم،","26:2":"ويكون طول كل قطعة ثماني وعشرين ذراعا (نحو أربعة عشر مترا) وعرضها أربع أذرع (نحو مترين) فيكون لجميع القطع قياس واحد.","26:3":"وتصل خمسة قطع منها ببعض، وكذلك افعل بالقطع الخمس الأخرى.","26:4":"واصنع عرى من قماش أزرق على حاشية الطرف الواحد في القطع الموصولة الأولى. وكذلك تفعل أيضا في حاشية الطرف الأخير من القطع الأخرى الموصولة.","26:5":"فيكون للطرف الأخير الواحد خمسون عروة في المجموعة الأولى، وخمسون عروة في طرف المجموعة الثانية، الواحدة مقابل الأخرى.","26:6":"ثم اصنع خمسين مشبكا من ذهب تصل بها عرى المجموعتين، فتتصل المجموعتان معا لتصبحا سقفا واحدا للمسكن.","26:7":"وتصنع أيضا سقفا ثانيا للمسكن، من إحدى عشرة قطعة من نسيج شعر المعزى.","26:8":"طول القطعة الواحدة ثلاثون ذراعا (نحو خمسة عشر مترا) وعرضها أربع أذرع (نحو مترين) فتكون كلها ذات مقاس واحد.","26:9":"وتصل خمس قطع معا لتصبح قطعة واحدة، وكذلك افعل بالقطع الست الأخرى. على أن تثني القطعة السادسة، فتتدلى كحجاب أمام واجهة المسكن.","26:10":"واصنع خمسين عروة على حاشية طرف واحد للمجموعة الأولى. وكذلك تصنع بحاشية طرف واحد للمجموعة الثانية.","26:11":"وتصنع خمسين مشبكا من نحاس تدخلها في العرى فتتصل المجموعتان معا، لتصبحا سقفا ثانيا للمسكن.","26:12":"ويتبقى لديك ذراع (نحو نصف المتر) من غطاء السقف مدلى لحجب مؤخر المسكن.","26:13":"والجزء الفاصل من طول القطع على كل جانب من بين الجانبين، تسدله على جانبي المسكن من هنا ومن هناك لتغطيه.","26:14":"وتصنع غطاء للخيمة من جلود بنفسجية اللون، وفوقه سقف آخر من جلود الدلفين.","26:15":"أما جدران المسكن فتصنعها من ألواح قائمة من خشب السنط.","26:16":"طول اللوح منها عشر أذرع (نحو خمسة أمتار) وعرضه ذراع ونصف (نحو خمسة وسبعين سنتيمترا)","26:17":"ولتكن لكل لوح رجلان متقابلتان إحداهما بإزاء الأخرى. هكذا تصنع لجميع ألواح المسكن.","26:18":"فتجعل الجانب الجنوبي للمسكن مكونا من عشرين لوحا.","26:19":"واصنع أربعين قاعدة من فضة تحت العشرين لوحا، فيكون لكل لوح منفرد قاعدتان لرجليه.","26:20":"واجعل لجانب المسكن الثاني الشمالي عشرين لوحا.","26:21":"واصنع له أيضا أربعين قاعدة من فضة، ليكون لكل لوح منفرد قاعدتان لرجليه.","26:22":"أما جدار مؤخر المسكن الغربي فتصنع له ستة ألواح.","26:23":"كما تصنع لوحين لزاويتي المسكن في المؤخر.","26:24":"على أن يكون كل منهما مزدوجا من أسفله إلى أعلاه، حيث تثبت في رأس كل مزدوج حلقة واحدة. كل منهما للزاويتين.","26:25":"فيكون هناك ثمانية ألواح للجانب الغربي، وست عشرة قاعدة من فضة، قاعدتان تحت كل لوح منفرد.","26:26":"وتصنع عوارض من خشب السنط، خمسا لألواح جانب المسكن الجنوبي.","26:27":"وخمس عوارض لألواح مؤخر المسكن الغربي.","26:28":"وتجعل العارضة الوسطى تنفذ في وسط الألواح من طرف إلى طرف.","26:29":"وتغشي الألواح برقائق من ذهب. واصنع لها حلقات من ذهب لتكون بيوتا للعوارض، وتغشي العوارض بذهب أيضا.","26:30":"وهكذا تقيم المسكن وفقا للمثال الذي أريتك إياه على الجبل.","26:31":"وتصنع ستارا من كتان مبروم ذي ألوان زرقاء وبنفسجية وحمراء، بعد أن يطرز عليه حائك ماهر رسم الكروبيم.","26:32":"وعلقه على أربعة أعمدة من خشب السنط مغشاة بذهب. لها أربعة خطاطيف من ذهب، وقائمة على أربع قواعد من فضة.","26:33":"وتجعل الستار تحت المشابك. ثم تأتي بتابوت الشهادة (الذي فيه لوحا الوصايا العشر) فتدخله إلى هناك، إلى ما وراء الستارة الفاصلة بين القدس وقدس الأقداس.","26:34":"وتضع الغطاء على تابوت الشهادة في قدس الأقداس.","26:35":"وتنصب المائدة خارج الستارة مقابل المنارة، فتكون المائدة قائمة في الجهة الجنوبية.","26:36":"وتصنع ستارة لمدخل المسكن، ذات ألوان زرقاء وبنفسجية وحمراء وخيوط كتان مبروم من تطريز حائك ماهر.","26:37":"وتجعل للستارة خمسة أعمدة من خشب السنط، ذات خطاطيف من ذهب، وتغشي الأعمدة بذهب وتسبك لها خمس قواعد من نحاس.","27:1":"وتصنع المذبح من خشب السنط. سطحه مربع الشكل. طوله خمسة أذرع (نحو مترين ونصف المتر) وعرضه خمسة أذرع (نحو مترين ونصف المتر) وارتفاعه ثلاثة أذرع (نحو متر ونصف المتر)","27:2":"وتصنع له قرونا تقيمها على زواياه الأربع، على أن تكون منحوتة من ذات خشب المذبح وفيه، وتغشيه بنحاس.","27:3":"وتصنع جميع آنيته من نحاس: قدوره لرفع رماده، ومجارفه وأحواضه ومناشله ومجامره.","27:4":"وتصنع له شبكة من نحاس ذات أربع حلقات من نحاس، مثبتة على أطرافه الأربعة.","27:5":"وتضعها تحت حافة المذبح من أسفل بحيث تصل إلى منتصفه.","27:6":"وتصنع للمذبح عصوين من خشب السنط وتغشيهما بالنحاس.","27:7":"وتدخل العصوين في الحلقات على جانبي المذبح ليحمل بهما.","27:8":"وتصنع المذبح مجوفا تماما من ألواح، بحسب المثال الذي أريتك إياه في الجبل.","27:9":"وتحيط ساحة المسكن من جهة الجنوب بستائر من كتان مجدول، طولها مئة ذراع (نحو خمسين مترا).","27:10":"ولها عشرون عمودا، وعشرون قاعدة من نحاس، وتكون خطاطيفها وقضبانها من فضة.","27:11":"وكذلك يكون الجانب الشمالي، إذ يكون طول ستائره مئة ذراع (نحو خمسين مترا) وأعمدته عشرون، قائمة على عشرين قاعدة من نحاس وخطاطيفه وقضبانه من فضة.","27:12":"أما عرض الدار الغربي فيكون طول ستائره خمسين ذراعا (نحو خمسة وعشرين مترا) معلقة على أعمدة عشرة ذات عشر قواعد.","27:13":"ويكون عرض الساحة من ناحية الشرق خمسين ذراعا (نحو خمسة وعشرين مترا).","27:14":"فيكون طول الستائر على الجانب الأول لمدخل الساحة خمس عشرة ذراعا (نحو سبعة أمتار ونصف المتر) معلقة على أعمدة ثلاثة ذات ثلاث قواعد.","27:15":"وكذلك يكون طول الستائر على الجانب الآخر لمدخل الساحة خمس عشرة ذراعا (نحو سبعة أمتار ونصف المتر)، معلقة على أعمدة ثلاثة ذات ثلاث قواعد.","27:16":"أما طول ستائر المدخل فيكون عشرين ذراعا (نحو عشرة أمتار) من كتان مبروم ذي ألوان زرقاء وبنفسجية وحمراء، من صناعة حائك ماهر، وتكون معلقة على أعمدة ذات أربع قواعد.","27:17":"ويحيط بكل أعمدة الدار قضبان من فضة، ذات خطاطيف من فضة وقواعد من نحاس.","27:18":"فيكون طول الساحة مئة ذراع (نحو خمسين مترا) وعرضها خمسين ذراعا (نحو خمسة وعشرين مترا) وارتفاع ستائرها خمس أذرع (نحو مترين ونصف المتر).","27:19":"ولتكن جميع الأواني المستعملة في خدمة المسكن والمشاجب وأوتاد المسكن والساحة مصنوعة من نحاس.","27:20":"وتأمر بني إسرائيل أن يقدموا إليك زيت زيتون مرضوض لإضاءة المنارة الدائمة.","27:21":"ويقوم هرون وبنوه من المساء إلى الصباح، بالمحافظة الدائمة على إضاءة السرج أمام الرب في خيمة الاجتماع، خارج الحجاب القائم أمام تابوت الشهادة فتكون هذه فريضة دهرية لبني إسرائيل في كل أجيالهم.","28:1":"وافرز لي هرون أخاك وأولاده: ناداب وأبيهو وألعازار وإيثامار، من بين بني إسرائيل، ليكونوا لي كهنة.","28:2":"واصنع لأخيك هرون ثيابا مقدسة لتضفي عليه مجدا وبهاء.","28:3":"وخاطب كل ذي مهارة ممن وهبتهم روح البراعة في الحياكة ليصنعوا ثياب هرون لتقديسه، فيكون كاهنا لي.","28:4":"وهذه هي الثياب التي يتوجب عليهم صناعتها: صدرة ورداء وجبة وقميص مخرم وعمامة وحزام، يصنعونها ثيابا مقدسة لهرون وأولاده، ليكونوا كهنة لي.","28:5":"وليستخدموا في حياكتها خيوطا ذهبية وزرقاء وبنفسجية وحمراء والكتان الفاخر.","28:6":"وليقم أمهر الخياطين على صناعة الرداء من خيوط ذهبية وزرقاء وبنفسجية وحمراء ومن الكتان المبروم.","28:7":"يكون له كتفان متصلان في طرفيه ليمكن تثبيته.","28:8":"أما الحزام الذي يشده، فيكون محاكا منه، مصنوعا بمهارة من خيوط ذهبية وزرقاء وبنفسجية وحمراء وكتان مبروم فاخر.","28:9":"ثم خذ حجري جزع، وانقش عليهما أسماء رؤساء بني إسرائيل.","28:10":"تنقش كل ستة أسماء على حجر واحد بحسب تاريخ ولادتهم.","28:11":"انقش أسماء رؤساء أسباط بني إسرائيل على الحجرين تماما مثل حفر النقاش الماهر على الخاتم، وطوقهما بإطارين من ذهب.","28:12":"وترصع كتفي الرداء بالحجرين، فيكونان حجري تذكار لبني إسرائيل، فيحمل هرون أسماءهم على كتفيه للتذكار أمام الرب.","28:13":"وتصنع طوقين من ذهب،","28:14":"وسلسلتين من ذهب خالص مبرومتين كحبل، تعلقهما بالطوقين.","28:15":"كلف أمهر الخياطين بصناعة «صدرة القضاء» من خيوط ذهبية وزرقاء وبنفسجية وحمراء وكتان مبروم على غرار صناعة الرداء.","28:16":"وتكون مربعة مثنية من طبقتين، وطولها شبر وعرضها شبر.","28:17":"وترصعونها بأربعة صفوف من الحجارة الكريمة. الصف الأول: عقيق أحمر وياقوت أصفر وزمرد.","28:18":"والصف الثاني: بهرمان وياقوت أزرق وعقيق أبيض.","28:19":"والصف الثالث: عين الهر ويشم وجمشت.","28:20":"والصف الرابع: زبرجد وجزع ويشب، وتؤطرها جميعها بأطواق ذهبية في ترصيعها.","28:21":"وتنقش على كل حجر كريم اسم سبط من أسباط بني إسرائيل الاثني عشر على غرار نقش الخاتم المحفورة عليه أسماء الاثني عشر سبطا.","28:22":"واصنع على الصدرة سلاسل مبرومة من ذهب خالص مثل الحبل المضفور.","28:23":"وتضع على طرفي الصدرة حلقتين من ذهب.","28:24":"وتجعل ضفيرتي الذهب في الحلقتين على طرفي الصدرة.","28:25":"كما تدخل طرفي الضفيرتين الآخرين في الطوقين، وتجعلهما على كتفي الرداء إلى أمامه.","28:26":"وتصنع حلقتين من ذهب وتثبتهما على طرفي الصدرة الداخلية الملاصقة للرداء.","28:27":"كذلك تصنع حلقتين من ذهب أخريين، وتضعهما على أسفل كتفي الرداء من الأمام عند مكان الوصل فوق حزام الرداء.","28:28":"وتربط حلقتي الصدرة إلى حلقتي الرداء بخيط أزرق لتثبت فوق حزام الرداء، وهكذا لا تنتزع الصدرة عن الرداء.","28:29":"فيحمل هرون أسماء أسباط بني إسرائيل في «صدرة القضاء» على قلبه عندما يدخل إلى القدس، تذكارا دائما أمام الرب","28:30":"وتضع أيضا في صدرة القضاء «الأوريم والتميم» ليحملها هرون على قلبه عندما يمثل أمام الرب. وهكذا يحمل هرون على قلبه أمام الرب دائما رمز قضاء بني إسرائيل.","28:31":"أما الجبة فتصنعها كلها من قماش أزرق،","28:32":"لها فتحة للرأس في وسطها، ذات حاشية محيطة مطرزة، صناعة حائك ماهر. على غرار فتحة القميص تكون، لكي لا تتمزق،","28:33":"وتتدلى من هدبها رمانات زرقاء وبنفسجية وحمراء، وتعلق بينها أجراسا من ذهب،","28:34":"فيكون بين كل رمانتين جرس من ذهب، وتجعلها جميعها على أذيال الجبة.","28:35":"فيرتدي هرون الجبة كلما دخل للخدمة، فتسمع أصواتها عند دخوله إلى القدس أمام الرب وعند خروجه، لئلا يموت.","28:36":"واصنع صفيحة من ذهب خالص، واحفر عليها كالحفر على خاتم: «قدس للرب»","28:37":"وثبتها بخيط أزرق في مقدمة عمامة هرون،","28:38":"فتكون دائما على جبهة هرون، فيحمل بذلك عن بني إسرائيل وزر أخطائهم في تقدماتهم التي يخصصونها للرب. وعلى هرون أن يتعمم بها دائما عندما يمثل أمام الرب، لكي يرضى الرب عنهم.","28:39":"وتصنع قميص هرون المخرم وعمامته من قماش كتاني، أما الحزام فتطرزه تطريز حائك ماهر.","28:40":"وكذلك تصنع لبني هرون أقمصة وأحزمة، وقلانس لتضفي عليهم مجدا وبهاء.","28:41":"وتلبسها هرون وبنيه. ثم امسحهم بزيت الزيتون، وكرسهم للخدمة التي يقومون بها، وتقدسهم ليكونوا كهنة لي.","28:42":"وتصنع لهم سراويل من كتان لستر العورة، تصل من الحقوين إلى الركبتين.","28:43":"فيلبسها هرون وبنوه تحت قمصانهم عند دخولهم إلى خيمة الاجتماع، أو عند اقترابهم إلى المذبح ليخدموا في القدس، لئلا يخطئوا فيموتوا. هذا فرض دائم على هرون ونسله جيلا بعد جيل.","29:1":"وهذا ما تقوم به لتكريس هرون وبنيه ليكونوا كهنة لي: خذ عجلا وكبشين خاليين من أي عيب.","29:2":"وتعد من دقيق القمح خبز فطير وكعكا معجونا بالزيت، ورقاق فطير مدهونة بزيت،","29:3":"وتضعها في سلة واحدة، وتقدمها في السلة مع العجل والكبشين.","29:4":"ثم تحضر هرون وبنيه إلى باب خيمة الاجتماع، وتدعهم يغتسلون بماء.","29:5":"وتلبس هرون القميص والجبة والرداء والصدرة وتشد الرداء عليه بالحزام المطرز.","29:6":"وتضع العمامة على رأسه وتثبت عليها الإكليل المقدس.","29:7":"وتأخذ دهن المسحة وتسكبه على رأسه وتمسحه تكريسا له،","29:8":"ثم تحضر بنيه وتلبسهم أقمصتهم المطرزة،","29:9":"وأحزمتهم فيكرسون كهنة فريضة لهم إلى الأبد. بهذه الطريقة تكرس هرون وبنيه كهنة.","29:10":"ثم أحضر العجل أمام خيمة الاجتماع، ليضع هرون وبنوه أيديهم على رأسه.","29:11":"فتذبح العجل أمام الرب عند باب خيمة الاجتماع.","29:12":"وتأخذ من دم العجل بإصبعك، وتضعه على قرون المذبح، وتصب بقية الدم عند قاعدة المذبح.","29:13":"ثم تأخذ جميع الشحم الذي يغشي الجوف، وزيادة الكبد والكليتين وما عليها من شحم، وتحرقها فوق المذبح.","29:14":"وأما لحم العجل وجلده وروثه، فتحرقها خارج المخيم، فإنه ذبيحة خطيئة.","29:15":"وتأخذ أحد الكبشين ليضع هرون وبنوه أيديهم عليه.","29:16":"تذبح الكبش، وتأخذ من دمه وترشه على المذبح.","29:17":"وتقطع الكبش إلى قطع، وتغسل أعضاءه الداخلية وأكارعه وتضعها مع رأس الكبش وقطعه على المذبح.","29:18":"وتحرق كامل الكبش على المذبح، فيكون محرقة للرب لنيل رضاه. هو قربان محرقة للرب.","29:19":"ثم تأخذ الكبش الثاني ليضع هرون وبنوه أيديهم عليه.","29:20":"ثم تذبحه وتأخذ من دمه وتضعه على شحمات آذان هرون وبنيه اليمنى، وكذلك على أباهم أيديهم وأرجلهم اليمنى، ثم ترش الدم على المذبح من كل ناحية.","29:21":"وتأخذ من الدم الذي على المذبح، ومن دهن المسحة، وتقطر منه على هرون وبنيه وعلى ثيابهم، فيتقدسون هم وثيابهم للرب.","29:22":"ثم تأخذ شحم الكبش وإليته والشحم الذي يغشي أعضاءه الداخلية، والمرارة والكليتين وما عليهما من شحم، والكتف اليمنى لأنه كبش تكريس.","29:23":"وتأخذ رغيف خبز واحدا، وكعكة واحدة معجونة بالزيت، ورقاقة واحدة من سلة الفطير التي قدمتها أمام الرب.","29:24":"وتضعها كلها في أيدي هرون وبنيه ليرجحوها أمام الرب.","29:25":"ثم تأخذها من أيديهم وتوقدها على المذبح فوق المحرقة لتكون رائحة رضى أمام الرب. هو قربان محرقة للرب.","29:26":"وتأخذ من ثم صدر كبش تكريس هرون وترجحه أمام الرب فيكون قسطك من الذبيحة.","29:27":"وعليك أن تقدس صدر ذبيحة الترجيح، وكتف ذبيحة تكريس هرون وبنيه الذي رجحته،","29:28":"فيكونان قسط هرون وبنيه. فريضة أبدية يقدمها بنو إسرائيل نصيب الكهنة من بني إسرائيل، من ذبائح سلامتهم تقدمة للرب.","29:29":"واحتفظوا بثياب هرون المقدسة لتكريس من يخلفه من نسله ومسحه.","29:30":"وعلى الابن الذي يخلفه كرئيس كهنة، أن يلبسها سبعة أيام عندما يدخل إلى خيمة الاجتماع ليخدم في القدس.","29:31":"وتأخذ لحم كبش التكريس وتطبخه في مكان مقدس.","29:32":"وعلى هرون وبنيه أن يأكلوا لحم الكبش، والخبز الذي في السلة عند مدخل خيمة الاجتماع.","29:33":"هم وحدهم يأكلون منه لأنه قد كفر به عنهم عند تكريسهم وتقديسهم، ولا يأكل منه أحد آخر لأنه مقدس.","29:34":"أما إذا تبقى شيء من لحم التكريس أو من الخبز حتى الصباح، فعليك أن تحرقه بالنار لا يؤكل منه لأنه مقدس.","29:35":"هكذا تصنع لهرون وبنيه بموجب كل ما أمرتك، إذ تكرسهم سبعة أيام.","29:36":"وتقدم خلالها ثورا في كل يوم ذبيحة خطيئة لأجل الكفارة. وتطهر المذبح بتكفيرك عليه. وتمسحه لتقديسه.","29:37":"سبعة أيام تقدم ذبيحة كفارة على المذبح وتقدسه، فيكون المذبح قدس أقداس. وكل ما يمسه يصبح مقدسا.","29:38":"وإليك ما تقدمه على المذبح: حملان حوليان كل يوم بصورة مستمرة.","29:39":"تقدم أحد الحملين في الصباح، وتقدم الثاني في المساء.","29:40":"وتقدم مع كل منهما عشرا (لترين ونصف اللتر) من الدقيق المعجون بربع الهين (لتر ونصف اللتر) من زيت الزيتون النقي، بعد أن تسكب عليه ربع الهين (لترا ونصف اللتر) من الخمر.","29:41":"وتقرب الحمل الثاني في المساء مع تقدمة دقيق وسكيب خمر، كما فعلت في الصباح، لتكون التقدمة رائحة رضى. هي قربان محرقة للرب.","29:42":"فتكون محرقة دائمة أمام الرب مدى أجيالكم. تقدم عند مدخل خيمة الاجتماع، حيث أجتمع بكم لأكلمك هناك.","29:43":"وأجتمع هناك أيضا ببني إسرائيل، فيتقدس المكان بمجدي.","29:44":"فأقدس خيمة الاجتماع والمذبح، كما أقدس هرون وبنيه أيضا.","29:45":"وأسكن بين شعب إسرائيل، وأكون لهم إلها،","29:46":"فيعلمون أنني أنا الرب إلههم الذي أخرجهم من ديار مصر لأقيم في وسطهم. أنا الرب إلههم.","30:1":"وتصنع مذبحا من خشب السنط لإحراق البخور،","30:2":"يكون ذا سطح مربع، طوله ذراع (نحو نصف المتر) وعرضه ذراع (نحو نصف المتر) ويكون ارتفاعه ذراعين (نحو متر)، وله قرون منحوتة في ذات خشبه.","30:3":"وتغشي سطحه وجوانبه وقرونه بذهب خالص، وطوقه بإطار من الذهب.","30:4":"وثبت على كل من جانبيه تحت الإطار، حلقتين مصنوعتين من الذهب، لتضع فيهما عصوين يحمل المذبح بهما.","30:5":"أما العصوان فاصنعهما من خشب السنط المغشى بذهب.","30:6":"وتضع هذا المذبح أمام الحجاب المواجه لتابوت الشهادة (الذي فيه لوحا الشريعة) مقابل الغطاء الذي فوق التابوت حيث أجتمع بك.","30:7":"فيحرق هرون عليه بخورا عطرا في كل صباح، عندما يدخل لإصلاح فتائل المنارة.","30:8":"وكذلك يحرقه أيضا عندما يضيء هرون المنارة في المساء. فيظل البخور موقدا أمام الرب من جيل إلى جيل.","30:9":"لا تحرق على هذا المذبح بخورا غريبا ولا محرقة أو تقدمة، ولا تسكبوا عليه سكيبا.","30:10":"ويقرب هرون كفارة على قرونه مرة في السنة فيرش من دم ذبيحة الخطيئة الكفارية عليه مرة في السنة من جيل إلى جيل، لأنه هو قدس أقداس للرب».","30:11":"وخاطب الرب موسى:","30:12":"«عندما تقوم بإحصاء بني إسرائيل، يقدم كل من تحصيه فدية عن نفسه للرب لئلا يصيبهم وبأ عند إحصائهم.","30:13":"فيعطي كل محصى نصف شاقل (نحو ستة جرامات) من الفضة تقدمة للرب.","30:14":"كل من جاز عليه الإحصاء من ابن عشرين سنة فما فوق، يعطي تقدمة للرب.","30:15":"فلا يعطي الغني أكثر من نصف شاقل (نحو ستة جرامات) ولا يدفع الفقير أقل منها لأنها تقدمة الرب، للتكفير عن نفوسكم.","30:16":"وتستخدم فضة الكفارة هذه التي تجمعها من بني إسرائيل، لنفقات خيمة الاجتماع. فتكون تذكارا. لبني إسرائيل أمام الرب للتكفير عن نفوسكم».","30:17":"وخاطب الرب موسى:","30:18":"«اصنع حوضا نحاسيا للاغتسال ذا قاعدة نحاسية، وأقمه بين خيمة الاجتماع والمذبح، واملأه بالماء،","30:19":"ليغسل هرون وبنوه أيديهم وأرجلهم منه،","30:20":"لدى دخولهم إلى خيمة الاجتماع، أو عند اقترابهم إلى المذبح للقيام بخدمة تقديم المحرقات لئلا يموتوا إذا لم يغتسلوا.","30:21":"ليغسلوا أيديهم وأرجلهم لئلا يموتوا. فتكون هذه فريضة أبدية لهرون ونسله جيلا بعد جيل».","30:22":"ثم قال الرب لموسى:","30:23":"خذ لك أطيب العطور: خمس مئة شاقل (نحو ستة كيلو جرامات) من المر النقي السائل، ومئتين وخمسين شاقلا (نحو ثلاثة كيلو جرامات) من القرفة، ومئتين وخمسين شاقلا (نحو ثلاثة كيلو جرامات) من قصب الذريرة.","30:24":"وخمس مئة شاقل (نحو ستة كيلو جرامات) من السليخة وهينا (نحو ستة لترات) من زيت الزيتون النقي.","30:25":"واصنع منها دهن مسحة مقدسا طيبا شذيا صنعة عطار ماهر، فيكون دهن مسحة مقدسا.","30:26":"تمسح به خيمة الاجتماع، وتابوت الشهادة،","30:27":"والمائدة مع كل آنيتها، والمنارة وآنيتها، ومذبح البخور،","30:28":"ومذبح المحرقة وسائر آنيته، والحوض وقاعدته.","30:29":"تقدسها فتصبح قدس أقداس، ويصبح كل ما مسها مقدسا.","30:30":"وتمسح هرون وبنيه أيضا وتقدسهم ليكونوا كهنة لي.","30:31":"وتقول لبني إسرائيل: إن هذا الدهن يكون لي دهنا مقدسا للمسحة على مر أجيالكم","30:32":"لا يسكب على جسد إنسان، ولا تستخدموا مقاديره في صناعة طيب مثله، فهو مقدس، ويجب أن يكون مقدسا عندكم.","30:33":"كل من ركب مثله أو دهن به غريبا من غير الكهنة يستأصل من بين قومه».","30:34":"وقال الرب لموسى: «خذ لك أطيابا، أجزاء متساوية من الميعة والأظفار والقنة العطرة واللبان الزكي، واخلطها،","30:35":"صانعا منها بخورا عطرا مملحا نقيا مقدسا، كما يفعل أمهر العطارين.","30:36":"وتسحق بعضا منه وتجعله أمام التابوت في خيمة الاجتماع حيث أجتمع بك. فيكون قدس أقداس عندكم.","30:37":"ولا يستخدم أحد مقاديره في صناعة بخور مثله. يكون مقدسا عندك للرب وحده.","30:38":"كل من يركب مثله ليشمه يستأصل من بين قومه».","31:1":"وخاطب الرب موسى:","31:2":"«ها أنا قد دعوت بصلئيل بن أوري، حفيد حور من سبط يهوذا، باسمه،","31:3":"وملأته من روح الله ووهبته حكمة ومهارة ومقدرة ومعرفة في كل أنواع الحرف،","31:4":"ولابتكار فنون التصميمات المصنوعة من الذهب والفضة والنحاس،","31:5":"وصقل الجواهر وترصيعها، ونجارة الخشب، وليكون محترفا لكل صناعة.","31:6":"كما اخترت أهوليآب بن أخيساماك من سبط دان، ليكون مساعدا له. وكذلك وهبت جميع الصناع مهارة خاصة ليقوموا بكل ما أمرتك به.","31:7":"في صنع خيمة الاجتماع وتابوت الشهادة والغطاء الذي عليه وسائر آنية الخيمة،","31:8":"كالمائدة وآنيتها، والمنارة الذهبية الطاهرة، وكل آنيتها، ومذبح البخور،","31:9":"ومذبح المحرقة وكل آنيته، وحوض الاغتسال وقاعدته.","31:10":"وكذلك الثياب المنسوجة، ثياب هرون الكاهن المقدسة وثياب بنيه القائمين على خدمة الكهانة،","31:11":"ودهن المسحة والبخور العطر للقدس. فيعملون هذه كلها بمقتضى كل ما أمرتك به».","31:12":"وقال الرب لموسى:","31:13":"«قل لبني إسرائيل: احفظوا أيام سبوتي لأنها علامة العهد الذي بيني وبينكم، على مر الأجيال، لتعلموا أني أنا الرب الذي يقدسكم.","31:14":"احفظوا يوم السبت لأنه مقدس لكم. من يدنسه حتما يمت. فكل من يقوم فيه بعمل، تستأصل تلك النفس من بين قومها.","31:15":"في ستة أيام تعملون، أما يوم السبت فهو يوم عطلة مقدس للرب. كل من يقوم بعمل في يوم السبت يقتل حتما.","31:16":"ليحفظ بنو إسرائيل السبت ويحتفلوا به في كل أجيالهم عهدا أبديا.","31:17":"هو بيني وبني إسرائيل علامة عهد إلى الأبد، لأنه في ستة أيام صنع الرب السماء والأرض، وفي اليوم السابع فرغ من العمل واستراح».","31:18":"وعندما فرغ الله من مخاطبة موسى في جبل سيناء، أعطاه لوحي الشهادة، وهما لوحان من حجر مكتوبان بإصبع الله.","32:1":"ولما رأى الشعب أن موسى قد طالت إقامته على الجبل، اجتمعوا حول هرون، وقالوا له: «هيا، اصنع لنا إلها يتقدمنا في مسيرنا، لأننا لا ندري ماذا أصاب هذا الرجل موسى الذي أخرجنا من ديار مصر».","32:2":"فأجابهم هرون: «انزعوا أقراط الذهب التي في آذان نسائكم وبناتكم وبنيكم، وأعطوني إياها».","32:3":"فنزعوها من آذانهم، وجاءوا بها إليه.","32:4":"فأخذها منهم وصهرها وصاغ عجلا. عندئذ قالوا: «هذه آلهتك يا إسرائيل التي أخرجتك من ديار مصر».","32:5":"وعندما شاهد هرون ذلك شيد مذبحا أمام العجل وأعلن: «غدا هو عيد للرب».","32:6":"فبكر الشعب في اليوم الثاني وأصعدوا محرقات وقدموا قرابين سلام. ثم احتفلوا فأكلوا وشربوا، ومن ثم قاموا للهو والمجون.","32:7":"فأمر الرب موسى: «قم وانزل فإن الشعب الذي قد أخرجته من ديار مصر، قد فسد.","32:8":"إذ انحرفوا سريعا عن الطريق الذي أمرتهم به، فصاغوا لهم عجلا وعبدوه وذبحوا له الذبائح هاتفين: هذا هو إلهك يا إسرائيل الذي أخرجك من ديار مصر».","32:9":"وقال الرب لموسى: «لقد تأملت في هذا الشعب، وإذا به شعب عنيد متصلب القلب.","32:10":"والآن دعني وغضبي المحتدم فأفنيهم، ثم أجعلك أنت شعبا عظيما».","32:11":"فابتهل موسى إلى الرب وقال: «لماذا يحتدم غضبك على شعبك الذي أخرجته من ديار مصر بقوة عظيمة وذراع مقتدرة؟","32:12":"لماذا يشمت المصريون فينا قائلين: لقد احتال عليهم إلههم فأخرجهم من ههنا ليهلكهم في الجبال ويفنيهم عن وجه الأرض. ارجع عن حمو غضبك ولا توقع هذا العقاب بشعبك.","32:13":"اذكر وعودك لعبيدك إبراهيم وإسحق وإسرائيل الذين أقسمت لهم بنفسك قائلا: أكثر نسلكم كنجوم السماء، وأهبكم جميع هذه الأرض التي وعدت بها فتملكونها إلى الأبد».","32:14":"فتراءف الرب ولم يوقع بشعبه العقاب الذي توعد به.","32:15":"ثم نزل موسى وانحدر من الجبل حاملا في يده لوحي الشهادة (الوصايا العشر)، وقد نقشت كتابة على وجهي كل منهما،","32:16":"وكان الله قد صنع اللوحين ونقش الكتابة عليهما.","32:17":"وسمع يشوع هتاف الشعب فقال لموسى: «هذا صوت تأهب لقتال في المخيم».","32:18":"فأجابه موسى: «هذا ليس هتاف نصرة ولا صراخ هزيمة، لكن ما أسمعه هو صوت غناء».","32:19":"وما إن اقترب موسى من المخيم وشاهد العجل والرقص حتى احتدم غضبه وألقى باللوحين من يده وكسرهما عند سفح الجبل.","32:20":"ثم أخذ العجل الذهبي وأحرقه بالنار وطحنه حتى صار ناعما، وذراه على وجه الماء وأرغمهم على الشرب منه.","32:21":"وقال موسى لهرون: «ماذا فعل بك هذا الشعب حتى جلبت عليه هذه الخطيئة العظيمة؟»","32:22":"فأجاب هرون: «لا يحتدم غضب سيدي. إنك تعرف شر هذا الشعب.","32:23":"لقد قالوا لي: اصنع لنا إلها يتقدمنا في مسيرنا، لأننا لا ندري ماذا أصاب هذا الرجل موسى الذي أخرجنا من ديار مصر،","32:24":"فقلت لهم من لديه ذهب فلينزعه ويعطني إياه، فطرحته في النار فخرج هذا العجل».","32:25":"ولما رأى موسى أن الشعب غارق في مجونه بعد أن أفلت هرون زمامهم فصاروا بذلك مثار سخرية أعدائهم،","32:26":"وقف في باب المخيم وصاح: «كل من يتبع الرب فليقبل إلي هنا». فاجتمع حوله اللاويون.","32:27":"فهتف بهم: «هذا ما يعلنه الرب إله بني إسرائيل: ليتقلد كل واحد سيفه، وجولوا في المخيم ذهابا وإيابا من مدخل إلى مدخل، واقتلوا كل داعر أخا كان أم صاحبا أم قريبا».","32:28":"فأطاع اللاويون أمر موسى. فقتل من الشعب في ذلك اليوم نحو ثلاثة آلاف رجل.","32:29":"عندئذ قال موسى للاويين: «لقد كرستم اليوم أنفسكم لخدمة الرب، وقد كلف ذلك كل واحد منكم قتل ابنه أو أخيه، ولكن لينعم عليكم الرب في هذا اليوم ببركة».","32:30":"وفي الغد قال موسى للشعب: «لقد ارتكبتم خطيئة عظيمة، وها أنا أعود إلى الجبل لأمثل أمام الرب، لعلي أحظى لكم بغفرانه».","32:31":"ورجع موسى إلى الرب وتضرع قائلا: «يا رب لقد اقترف هذا الشعب خطيئة عظيمة، وصاغوا لأنفسهم إلها من ذهب.","32:32":"والآن إن شئت، فاغفر لهم، وإلا فامحني من كتابك الذي كتبت».","32:33":"فأجاب الرب موسى: «الذي أخطأ إلي أمحوه من كتابي","32:34":"والآن اذهب، وقد الشعب إلى المكان الذي ذكرته لك. وها هو ملاكي يتقدمك، ولكن لابد من معاقبة الشعب على خطيئتهم في يوم قضائي».","32:35":"وضرب الرب الشعب بالوبأ عقابا لهم على عبادة العجل الذي صنعه هرون.","33:1":"وقال الرب لموسى: «اترك هذا المكان أنت والشعب الذي أصعدته من ديار مصر، وامض إلى الأرض التي أقسمت لإبراهيم وإسحق ويعقوب قائلا: سأهبها لنسلك.","33:2":"وسأرسل أمامك ملاكا، وأطرد الكنعانيين والأموريين والحثيين والفرزيين والحويين واليبوسيين.","33:3":"إنها أرض تفيض لبنا وعسلا. أما أنا فلن أسير في وسطكم لأنكم شعب متصلب القلب لئلا أفنيكم في الطريق».","33:4":"فلما سمع الشعب هذا الكلام القاسي، شرعوا في النوح، ولم يتزين أحد منهم.","33:5":"وكان الرب قد قال لموسى: «قل لبني إسرائيل أنتم شعب متصلب القلب، لهذا إن بقيت لحظة واحدة في وسطكم أفنيكم. ولكن الآن انزعوا زينتكم عنكم إلى أن أتخذ قراري بشأنكم».","33:6":"فخلع الشعب زينتهم عند جبل حوريب.","33:7":"وأخذ موسى خيمة ونصبها بعيدا خارج المخيم، ودعاها خيمة الاجتماع. فكان كل ملتمس للرب يسعى إلى خيمة الاجتماع القائمة خارج المخيم.","33:8":"وكلما مضى موسى إلى الخيمة، كان كل واحد من الشعب يقف في باب خيمته، ويتابعونه بأنظارهم إلى أن يدخلها.","33:9":"وما إن يتوارى موسى فيها، حتى ينزل عمود السحاب ويقف عند مدخلها، فيتكلم الرب مع موسى،","33:10":"فيشاهد جميع الشعب عمود السحاب واقفا عند باب الخيمة، فيسجدون للرب، كل واحد أمام باب خيمته،","33:11":"فكان الرب يكلم موسى وجها لوجه كما يكلم الإنسان صاحبه. وإذا رجع موسى إلى المخيم، كان خادمه الشاب يشوع بن نون يمكث داخل الخيمة.","33:12":"وقال موسى للرب: «ها أنت قد قلت لي: قد هذا الشعب، ولكن لم تعلمني من سترسل معي. ثم قلت: إني عرفتك باسمك وحظيت برضاي.","33:13":"فالآن إن كنت حقا قد حظيت برضاك، فأرشدني إلى طريقك لكي أسلك حسب قصدك، وأحظى بمسرتك، واذكر أيضا أن هذه الأمة هي شعبك».","33:14":"فأجابه: «إني أرافقك فأريحك».","33:15":"فقال موسى: «إن لم ترافقنا، فلا تصعدنا من هنا،","33:16":"إذ كيف يدرك أنني وشعبك قد حظينا برضاك؟ أليس بمرافقتك لنا، فنتميز أنا وشعبك بذلك عن جميع الشعوب الساكنين في الأرض؟»","33:17":"فأجاب الرب موسى: «سأفعل عين هذا الأمر الذي التمسته. لأنك حظيت برضاي وأنا عرفتك باسمك».","33:18":"وقال موسى: «أرني مجدك».","33:19":"فقال الرب: «أجيز إحساناتي أمامك، وأذيع اسمي (الرب) أمامك. أغدق رأفتي على من أشاء ورحمتي على من أريد»،","33:20":"وأضاف: «ولكنك لن ترى وجهي، لأن الإنسان الذي يراني لا يعيش».","33:21":"ثم قال الرب: «لدي مكان قريب مني. فقف على الصخرة،","33:22":"وعندما يعبر مجدي، أضعك في نقرة من الصخر، وأحجبك بيدي حتى أعبر،","33:23":"ثم أرفع يدي فتنظر ورائي، أما وجهي فيظل محجوبا عن العيان».","34:1":"ثم قال الرب لموسى: «انحت لك لوحين من حجر مثل اللوحين الأولين. فأكتب أنا عليهما الكلمات التي دونتها على اللوحين الأولين اللذين كسرتهما.","34:2":"وتأهب في الصباح ثم اصعد إلى جبل سيناء، وامثل أمامي هناك على قمة الجبل.","34:3":"ولا يصعد معك أحد، ولا يشاهد على الجبل إنسان، ولا ترع الغنم أيضا والبقر باتجاه هذا الجبل».","34:4":"فنحت موسى لوحين من حجر مماثلين للأولين، وبكر في الصباح وصعد إلى جبل سيناء حسب أمر الرب.","34:5":"فنزل بهيئة سحاب، ووقف معه هناك حيث أعلن له اسمه: «الرب»،","34:6":"وعبر من أمام موسى مناديا: «أنا الرب. الرب إله رؤوف رحيم، بطيء الغضب وكثير الإحسان والوفاء.","34:7":"أدخر الإحسان وأغفر الإثم والمعصية والخطيئة. ولكني لا أعفي المذنب من العقاب، بل أفتقد إثم الآباء في الأبناء والأحفاد حتى الجيل الرابع».","34:8":"فخر موسى في الحال وسجد،","34:9":"وقال: «إن حظيت برضاك أيها السيد، فليرافقنا الرب في مسيرنا. ومع أن هذا الشعب عنيد. لكن اصفح عن إثمنا وخطيئتنا واتخذنا شعبا خاصا لك».","34:10":"فأجاب الرب: «ها أنا أقطع معك عهدا، فأجري أمام جميع شعبك معجزات لم يجر مثيلها في جميع أمم الأرض كلها، فيشهد الشعب الذي تقيم في وسطه، الفعل المهول الذي أصنعه من أجلك.","34:11":"ولكن أطع ما أوصيتك اليوم به. ها أنا طارد من أمامك الأموريين والكنعانيين والحثيين والفرزيين والحويين واليبوسيين.","34:12":"إياك أن تعقد معاهدة مع سكان الأرض التي أنت ماض إليها لئلا يكونوا شركا لكم.","34:13":"بل اهدموا مذابحهم، واكسروا أصنامهم، واقطعوا أشجارهم المقدسة.","34:14":"إياكم أن تعبدوا إلها آخر غيري، لأن الرب اسمه غيور جدا.","34:15":"إياكم أن تعقدوا معاهدة مع سكان الأرض، لأنهم حين يعبدون آلهتهم مشركين ويذبحون لهم، يدعونكم فتأكلون من ذبيحتهم.","34:16":"وتزوجون بنيكم من بناتهم، فيجعلن بنيكم يغوون أيضا بعبادة آلهتهن.","34:17":"إياك أن تصنع آلهة مسبوكة.","34:18":"احتفلوا بعيد الفطير، فتأكلون فطيرا سبعة أيام كما أمرتكم في شهر أبيب (أي شهر نيسان وهو الشهر الأول من السنة العبرية)، لأنكم في هذا الشهر خرجتم من مصر.","34:19":"كل بكر ذكر هو لي، وكذلك كل بكر من ماشيتك من الثيران والخرفان والماعز.","34:20":"أما بكر الحمار فتفديه بحمل، وإلا تدق عنقه. كل ابن بكر لك تفديه بحمل. لا تمثلوا أمامي بأيد فارغة.","34:21":"في ستة أيام تعمل، وفي اليوم السابع تستريح، حتى لو كان ذلك في مواسم الفلاحة والحصاد.","34:22":"احتفلوا أيضا بعيد الأسابيع في أول حصاد القمح. وبعيد الجمع في آخر السنة.","34:23":"على جميع الذكور أن يمثلوا ثلاث مرات في السنة أمام السيد الرب إله إسرائيل.","34:24":"ها أنا أطرد الأمم من أمامكم، وأوسع حدودكم، ولن يطمع أحد في أرضكم حين تصعدون للمثول أمام الرب إلهكم ثلاث مرات في السنة.","34:25":"لا تقرب دم ذبيحة مع عجين مختمر. ولا تترك شيئا من ذبيحة الفصح إلى اليوم التالي.","34:26":"تحضر إلى بيت الرب إلهك باكورة ثمار أرضك. ولا تطبخ جديا في لبن أمه».","34:27":"واستطرد الرب: «دون هذه الكلمات، لأنني قطعت معك ومع إسرائيل عهدا بناء عليها».","34:28":"ومكث موسى في حضرة الرب أربعين يوما وأربعين ليلة، لم يأكل فيها خبزا، ولم يشرب ماء. فدون على اللوحين كلمات العهد، أي الوصايا العشر.","34:29":"وعندما انحدر من جبل سيناء حاملا بيديه لوحي الشهادة، لم يكن يدري أن وجهه كان يلمع لأنه كان يتحدث مع الله.","34:30":"وحين شاهد هرون وبنو إسرائيل موسى، كان وجهه لامعا، فخافوا أن يقتربوا منه،","34:31":"فدعاهم موسى فرجع إليه هرون ورؤساء الشعب فخاطبهم.","34:32":"وما لبث أن اقترب منه جميع بني إسرائيل، فتلا عليهم كل الوصايا التي أملاها الرب في جبل سيناء.","34:33":"وعندما أنهى موسى حديثه معهم، وضع على وجهه برقعا،","34:34":"كان يخلعه عند مثوله أمام الرب ليتحادث معه إلى أن ينصرف من لدنه، ثم يخرج ليخاطب بني إسرائيل بما أوصاه.","34:35":"فإذا عاين بنو إسرائيل لمعانا في جلد وجه موسى، كان يرد البرقع إلى حين دخوله إلى الخيمة للتحدث مع الرب فيرفعه.","35:1":"وعقد موسى اجتماعا لكل شعب إسرائيل وقال لهم: «هذه هي الأمور التي أوصى الرب أن تطيعوها:","35:2":"ستة أيام تنصرفون فيها إلى أعمالكم. أما السابع فيكون يوم راحة لكم مقدسا لعبادة الرب. كل من يقوم فيه بأي عمل يقتل.","35:3":"لا توقدوا نارا في بيوتكم في يوم السبت».","35:4":"ثم قال موسى لكل شعب إسرائيل: «هذا هو أمر الرب:","35:5":"هاتوا مما لديكم تقدمة للرب. كل من هو سخي النفس فليتبرع بتقدمة للرب: ذهبا وفضة ونحاسا،","35:6":"وأقمشة زرقاء وبنفسجية وحمراء، ومنسوجات كتانية، ومن شعر المعزى،","35:7":"وجلود كباش، وجلود دلفين، وخشب السنط،","35:8":"وزيتا للإنارة، وأطيابا لدهن المسحة وللبخور العطر،","35:9":"وحجارة جزع، وحجارة كريمة لترصيع الرداء والصدرة.","35:10":"وليتقدم كل صانع ماهر بينكم لتنفيذ ما أمر به الرب:","35:11":"المسكن وخيمته وسقوفها ومشابكها وألواحها وعوارضها وأعمدتها وقواعد الأعمدة،","35:12":"والتابوت وعصويه، وغطاء الكفارة، والستار الذي يحجب التابوت،","35:13":"والمائدة وعصويها، وجميع أوانيها، وخبز التقدمة.","35:14":"ومنارة الإضاءة وأوانيها وسرجها وزيت ضوئها،","35:15":"ومذبح البخور وعصويه، ودهن المسحة، والبخور العطر، وستار باب مدخل المسكن،","35:16":"ومذبح المحرقة، وشبكته النحاسية وعصويه وكل أوانيه، وحوض الاغتسال وقاعدته،","35:17":"وستائر ساحة المسكن وأعمدتها، وقواعد الأعمدة، وستار الساحة،","35:18":"وأوتاد الخيمة والساحة وحبالهما،","35:19":"وثياب هرون الكاهن، وثياب بنيه المقدسة، والثياب المنسوجة للخدمة في المقدس».","35:20":"فانصرف كل شعب إسرائيل من قدام موسى.","35:21":"ثم أقبل كل من حثه قلبه، وكل من سخت نفسه، حاملين تقدمة الرب، لإقامة خيمة الاجتماع وأواني خدمتها ولتجهيز الثياب المقدسة.","35:22":"وتوافد الرجال مع النساء من ذوي النفوس السخية، متبرعين بأساور وأقراط وخواتم وقلائد وغير ذلك من الأمتعة الذهبية، فكانت كل تقدمات المتبرعين من الذهب للرب.","35:23":"وكذلك كل من وجد لديه أقمشة زرقاء وبنفسجية وحمراء، ومنسوجات كتانية، ومن شعر المعزى، وجلود كباش، وجلود دلفين، تبرع بها.","35:24":"ومنهم أيضا من تبرع بتقدمات فضة ونحاس، جاء بها للرب وكل من وجد لديه خشب سنط صالح للاستخدام في عمل ما، تبرع به.","35:25":"وغزلت جميع النساء الماهرات بأيديهن منسوجات من خيوط زرقاء وبنفسجية وحمراء، ومنسوجات كتانية،","35:26":"كما غزلت النساء اللواتي حثتهن قلوبهن، منسوجات من شعر المعزى.","35:27":"وتبرع وجهاء الشعب بحجارة الجزع وحجارة كريمة لترصيع الرداء والصدرة،","35:28":"وبالأطياب وزيت الإنارة ولدهن المسحة وللبخور العطر.","35:29":"فتبرع جميع الرجال والنساء من بني إسرائيل، ممن سخت قلوبهم، مقدمين شيئا للرب لتنفيذ كل العمل الذي كلف الرب موسى بالإشراف على إنجازه.","35:30":"وقال موسى لبني إسرائيل: «ها إن الرب قد دعا بصلئيل بن أوري حفيد حور، من سبط يهوذا باسمه،","35:31":"وملأه من روح الله ووهبه الحكمة والمهارة والمعرفة في كل أنواع الحرف،","35:32":"لابتكار فنون التصميمات المصنوعة من الذهب والفضة والنحاس،","35:33":"ونقش الحجارة وترصيعها، ونجارة الخشب، وليكون محترفا لكل صناعة.","35:34":"وقد منحه الرب هو وأهوليآب بن أخيساماك من دان، القدرة على تعليم الآخرين.","35:35":"وجعلهما حاذقين متفوقين في صناعة نقش الجواهر والنجارة والحياكة، وتطريز المنسوجات الزرقاء والبنفسجية والحمراء والمنسوجات الكتانية، وسائر حرف النسيج، وفي كل حرفة صانع ومبتكر تصميم».","36:1":"وهكذا يقوم بصلئيل وأهوليآب وكل صانع حاذق وهبه الرب مقدرة في تنفيذ بناء خيمة الاجتماع، بإنجاز العمل، بحسب كل ما أمر به الرب.","36:2":"ثم استدعى موسى بصلئيل وأهوليآب وكل صانع ماهر وهبه الرب حذاقة، وكل من حثه قلبه على المساهمة في إنجاز عمل ما.","36:3":"وتسلموا من موسى جميع تقدمات بني إسرائيل، التي تبرعوا بها لبناء المقدس. وظل الشعب يأتون كل صباح بمزيد من التبرعات.","36:4":"فأقبل الصناع المهرة القائمون بأعمال المقدس، من مهامهم،","36:5":"وقالوا لموسى: «إن الشعب يأتي بما يفيض عما نحتاج إليه لإنجاز العمل الذي أمر به الرب».","36:6":"فأمر موسى أن يذيعوا في المخيم بالامتناع عن تقديم تبرعات. فكف الشعب عن ذلك.","36:7":"لأن ما لديهم، كان كافيا لتنفيذ العمل كله، وأكثر.","36:8":"أما الصناع الحاذقون بين الحرفيين فقد صنعوا سقف المسكن من عشر قطع من كتان مبروم، ذات ألوان زرقاء وبنفسجية وحمراء، طرز عليها حائك ماهر رسم الكروبيم.","36:9":"وكان طول كل قطعة ثماني وعشرين ذراعا (نحو أربعة عشر مترا) وعرضه أربع أذرع (نحو مترين). فكانت جميعها ذات قياس واحد.","36:10":"ووصلوا خمس قطع منها بعضها ببعض، وكذلك وصلت القطع الخمس الأخرى","36:11":"وصنعوا عرى من قماش على حاشية الطرف الواحد من القطع الموصولة الأولى، وكذلك فعلوا أيضا في حاشية الطرف الأخير من القطع الأخرى الموصولة","36:12":"فكان في الطرف الأخير من المجموعة الأولى خمسون عروة، وخمسون عروة في طرف المجموعة الثانية، الواحدة مقابل الأخرى.","36:13":"وصنعوا خمسين مشبكا من ذهب وصلت بها عرى المجموعتين، فأصبحتا سقفا واحدا للمسكن.","36:14":"وحاكوا أيضا سقفا ثانيا للمسكن من إحدى عشرة قطعة، مصنوعة من نسيج شعر المعزى.","36:15":"طول القطعة الواحدة ثلاثون ذراعا (نحو خمسة عشر مترا) وعرضها أربع أذرع (نحو مترين). فكانت جميعها ذات مقياس واحد.","36:16":"ووصلوا خمسة قطع معا لتكون قطعة واحدة، وكذلك فعلوا بالقطع الست الأخرى","36:17":"وصنعوا خمسين عروة على حاشية طرف واحد للمجموعة الأولى، وثبتوا خمسين عروة أخرى على حاشية طرف واحد من المجموعة الثانية.","36:18":"وصنعوا خمسين مشبكا من نحاس لتصل عري المجموعتين معا لتصبحا سقفا ثانيا للمسكن.","36:19":"وعملوا غطاء للخيمة من جلود كباش مدبوغة باللون الأحمر، ونصبوا فوقه سقفا آخر من جلود بنفسجية.","36:20":"وصنعوا جدران المسكن من ألواح قائمة من خشب السنط.","36:21":"طول اللوح منها عشر أذرع (نحو خمسة أمتار) وعرضه ذراع ونصف (نحو خمسة وسبعين سنتيمترا).","36:22":"ولكل لوح رجلان متقابلتان، إحداهما بإزاء الأخرى. هكذا بنوا جميع ألواح المسكن.","36:23":"وجعلوا الجانب الجنوبي للمسكن مكونا من عشرين لوحا.","36:24":"وصنعوا أربعين قاعدة من فضة تحت العشرين لوحا. فكان لكل لوح منفرد قاعدتان لرجليه.","36:25":"أما جانب المسكن الثاني الشمالي، فكان له أيضا عشرون لوحا،","36:26":"وأربعون قاعدة من فضة، فكان لكل لوح منفرد قاعدتان لرجليه.","36:27":"وبنوا جدار مؤخر المسكن الغربي من ستة ألواح.","36:28":"وصنعوا لوحين لزاويتي المسكن في المؤخر.","36:29":"فكان كل منهما مزدوجا من أسفله إلى أعلاه، حيث تثبت في رأس كل مزدوج حلقة واحدة. هكذا يكون كل منهما للزاويتين.","36:30":"فكانت في مجموعها ثمانية ألواح وست عشرة قاعدة من فضة، قاعدتين لكل لوح منفرد.","36:31":"وصنعوا عوارض من خشب السنط، خمسا لألواح جانب المسكن الجنوبي،","36:32":"وخمسا لألواح جانب المسكن الشمالي، وخمس عوارض لألواح مؤخر المسكن الغربي،","36:33":"وجعلوا العارضة الوسطى تنفذ في وسط الألواح من طرف إلى طرف","36:34":"وغشوا الألواح برقائق من ذهب. وصنعوا لها حلقات من ذهب لتكون بيوتا للعوارض. وكذلك غشوا العوارض بالذهب.","36:35":"وصنعوا الحجاب من كتان مبروم ذي ألوان زرقاء وبنفسجية وحمراء، بعد أن حاك عليه حائك ماهر رسم الكروبيم.","36:36":"وصنعوا له أربعة أعمدة من خشب السنط مغشاة بذهب، لها أربعة خطاطيف من ذهب، وقائمة على أربع قواعد من فضة.","36:37":"ونسجوا ستارا لمدخل المسكن ذا ألوان زرقاء وبنفسجية وحمراء، وخيوط كتان مبروم من تطريز حائك ماهر.","36:38":"له خمسة أعمدة، ذات خطاطيف وغشوا رؤوسها وقضبانها بذهب وسبكوا لها خمس قواعد من نحاس.","37:1":"ثم صنع بصلئيل التابوت من خشب السنط، طوله ذراعان ونصف (نحو متر وربع المتر) وعرضه ذراع ونصف (نحو خمسة وسبعين سنتيمترا) وارتفاعه ذراع ونصف (نحو خمسة وسبعين سنتيمترا).","37:2":"وغشى جدرانه الداخلية والخارجية بذهب خالص، وجعل له إطارا من ذهب.","37:3":"وسبك له أربع حلقات من ذهب، ثبتها على قوائمه الأربع، حلقتين من كل جانب.","37:4":"وصنع عصوين من خشب السنط غشاهما بالذهب.","37:5":"وأدخلهما في الحلقات المثبتة على جانبي التابوت ليحمل بهما.","37:6":"وصنع بصلئيل غطاء من ذهب خالص، طوله ذراعان ونصف (نحو متر وربع المتر) وعرضه ذراع ونصف (نحو خمسة وسبعين سنتيمترا)","37:7":"وخرط كروبين من ذهب أقامهما على طرفي الغطاء.","37:8":"فصنع كروبا واحدا على كل طرف من الغطاء، مخروطين من الغطاء نفسه، وقائمين على طرفيه.","37:9":"وكان الكروبان متواجهين باسطين أجنحتهما إلى فوق، يظللان بهما الغطاء، ويتجهان بوجهيهما نحوه.","37:10":"وصنع مائدة من خشب السنط طولها ذراعان (نحو متر) وعرضها ذراع (نحو نصف المتر) وارتفاعها ذراع ونصف (نحو خمسة وسبعين سنتيمترا).","37:11":"وغشاها بالذهب الخالص. وصنع لها إطارا عاليا من الذهب.","37:12":"وأحاطها بحافة عرضها شبر. وصنع لمحيط الحافة إطارا من ذهب.","37:13":"وسبك لها أربع حلقات من ذهب، ثبتها على زوايا قوائمها الأربع.","37:14":"فكانت الحلقات المثبتة على الحافة أماكن لعصوين، تحمل بهما المائدة.","37:15":"وصنع العصوين من خشب السنط، وغشاهما بالذهب لتحمل بهما المائدة.","37:16":"أما صحاف المائدة وصحونها وكؤوسها وأباريقها التي يسكب بها، فصاغها من ذهب خالص.","37:17":"وخرط المنارة من ذهب خالص، فكانت قاعدتها وساقها وكاساتها وبراعمها وأزهارها كلها مخروطة معا من قطعة واحدة،","37:18":"ولها ست شعب. يتفرع من كل جانب منها ثلاث شعب منارة.","37:19":"وفي كل شعبة ثلاث كاسات لوزية ببرعم وزهر. وهكذا إلى الستة الأفرع المتشعبة من المنارة.","37:20":"وعلى المنارة أربع كاسات لوزية ببراعمها وأزهارها.","37:21":"وجعل تحت كل فرعين من الأفرع المتشعبة من المنارة برعما، وهكذا فعل للستة الأفرع.","37:22":"فكانت براعمها وأفرعها المصنوعة من الذهب الخالص، مخروطة كلها من قطعة واحدة.","37:23":"وصنع لها سبعة سرج مع ملاقطها ومنافضها من ذهب خالص.","37:24":"فكان وزن الذهب الخالص المصاغ في صنعها وصنع أوانيها وزنة (نحو ستة وثلاثين كيلو جراما).","37:25":"وصنع مذبح البخور من خشب السنط، فكان سطحه مربعا، طوله ذراع (نحو نصف المتر)، وعرضه ذراع (نحو نصف المتر) وارتفاعه ذراعان (نحو متر). وكانت قرونه مخروطة منه.","37:26":"وغشى سطحه وجدرانه وقرونه بذهب خالص. وطوقه بإطار من ذهب.","37:27":"وصنع له أربع حلقات من ذهب، ثبت كل اثنتين منها تحت الإطار على جانبيه، لتوضع فيها العصوان اللتان يحمل بهما المذبح.","37:28":"وصنع العصوين من خشب السنط المغشى بالذهب","37:29":"وصنع دهن المسحة المقدس والبخور العطر النقي كما يصنعها عطار حاذق.","38:1":"وصنع مذبح المحرقة من خشب السنط، فكان سطحه مربع الشكل، طوله خمس أذرع (نحو مترين ونصف المتر)، وعرضه خمس أذرع (نحو مترين ونصف المتر)، وارتفاعه ثلاثة أذرع (نحو متر ونصف المتر).","38:2":"وصنع له قرونا، أقامها على زواياه الأربع، مخروطة من ذات خشبه. وغشاه بنحاس.","38:3":"وكذلك طرق من نحاس جميع آنية المذبح: القدور والمجارف والأحواض والمناشل والمجامر.","38:4":"وصنع للمذبح شبكة نحاسية، وضعها تحت حافة المذبح من أسفل، بحيث تصل إلى منتصفه.","38:5":"وسكب أربع حلقات نحاسية على أطراف الشبكة النحاسية لإدخال العصوين فيها.","38:6":"وصنع العصوين من خشب السنط المغشى بالنحاس.","38:7":"وأدخل العصوين في الحلقات المثبتة على جانبي المذبح، ليحمل بهما. وكان المذبح مجوفا مصنوعا من ألواح.","38:8":"وصنع حوض الاغتسال وقاعدته من نحاس. صهرها من المرايا النحاسية التي تبرعت بها النساء اللواتي احتشدن عند مدخل خيمة الاجتماع.","38:9":"وأحاط بصلئيل ساحة المسكن من جهة الجنوب بستائر من كتان مبروم، طولها مئة ذراع (نحو خمسين مترا).","38:10":"لها عشرون عمودا، ذات عشرين قاعدة نحاسية بخطاطيف وقضبان من فضة.","38:11":"وكذلك جعل طول ستائر الجانب الشمالي مئة ذراع (نحو خمسين مترا) وأعمدته عشرين عمودا ذات عشرين قاعدة نحاسية، بخطاطيف وقضبان من فضة.","38:12":"أما الجانب الغربي فقد كان طول ستائره خمسين ذراعا (نحو خمسة وعشرين مترا) معلقة بخطاطيف وقضبان من فضة، على أعمدة ذات عشر قواعد.","38:13":"وكذلك الجانب الشرقي فقد كان طوله خمسين ذراعا (نحو خمسة وعشرين مترا).","38:14":"فكان طول الستائر على الجانب الجنوبي لمدخل الساحة خمس عشرة ذراعا (نحو سبعة أمتار ونصف المتر)، معلقة على ثلاثة أعمدة ذات ثلاث قواعد.","38:15":"أما طول الستائر على الجانب الآخر (أي الشمالي) لمدخل الساحة فكان خمس عشرة ذراعا (نحو سبعة أمتار ونصف المتر)، معلقة على ثلاثة أعمدة ذات ثلاث قواعد.","38:16":"وكانت جميع الستائر المحيطة بالساحة منسوجة من كتان نقي مبروم.","38:17":"وصنع قواعد الأعمدة من نحاس. أما المشابك والقضبان فكانت من فضة، وتيجان الأعمدة مغطاة بالفضة. وجميع أعمدة الساحة موصولة بقضبان من فضة.","38:18":"وكان عرض ستار مدخل ساحة المسكن عشرين ذراعا (نحو عشرة أمتار) وارتفاعه خمس أذرع (نحو مترين ونصف المتر)، كارتفاع الساحة، وهو مصنوع من كتان ذي ألوان زرقاء وبنفسجية وحمراء من صناعة حائك ماهر.","38:19":"وعلقه بخطاطيف فضية على أربعة أعمدة فضية فوق أربع قواعد نحاسية. وكانت تيجان الأعمدة وقضبانها من فضة.","38:20":"أما جميع أوتاد الخيمة والساحة المحيطة بها، فقد كانت من نحاس.","38:21":"وما يلي المقادير المستخدمة في بناء مسكن الشهادة، التي تم حسابها بمقتضى أمر موسى، بإشراف اللاويين على يد إيثامار بن هرون الكاهن.","38:22":"وكان بصلئيل بن أوري حفيد حور من سبط يهوذا، هو الذي صنع كل ما أمر به الرب موسى.","38:23":"يعاونه أهوليآب بن أخيساماك من سبط دان، الذي برع في النقش والتوشية والتطريز بالألوان الزرقاء والبنفسجية والحمراء وخيوط الكتان البيضاء.","38:24":"كان وزن الذهب المستخدم في جميع عمل المسكن من التبرعات تسعا وعشرين وزنة وسبع مئة وثلاثين شاقلا (نحو ألف وثلاثة وخمسين كيلو جراما) طبقا لموازين المقدس.","38:25":"أما وزن الفضة المجباة من المعدودين من الشعب، فكان مئة وزنة وألفا وسبع مئة وخمسة وسبعين شاقلا (نحو ثلاثة آلاف وست مئة وواحد وعشرين كيلو جراما) طبقا لموازين المقدس.","38:26":"إذ كان يفرض على كل شخص من المعدودين بلغ من العمر عشرين سنة وما فوق، نصف شاقل (نحو ستة جرامات) طبقا لموازين المقدس. وكان عدد المعدودين نحو ست مئة وثلاثة آلاف رجل وخمس مئة وخمسين رجلا","38:27":"وكان وزن الفضة المستهلكة في صب قواعد المسكن والستائر المئة مئة وزنة (نحو ثلاثة آلاف وست مئة كيلو جرام)، أي وزنة واحدة (نحو ستة وثلاثين كيلو جراما) لكل قاعدة.","38:28":"أما ما فضل من الفضة البالغة ألف وسبع مئة وخمسة وسبعين شاقلا (نحو واحد وعشرين كيلو جراما) فقد استخدمت في صنع خطاطيف الأعمدة والقضبان وتغشية تيجان الأعمدة.","38:29":"وكان وزن النحاس الذي تبرع به الشعب سبعين وزنة وألفين وأربع مئة شاقل (نحو ألفين وخمس مئة وتسعة وأربعين كيلو جراما).","38:30":"ومنه صب قواعد باب خيمة الاجتماع ومذبح النحاس وشبكته النحاسية وجميع أوانيه.","38:31":"وقواعد الساحة المحيطة بالخيمة، وقواعد مدخلها وجميع أوتاد المسكن والدار المحيطة به.","39:1":"وحاكوا من الخيوط الزرقاء والبنفسجية والحمراء ثيابا منسوجة لارتدائها في أثناء خدمة المقدس، وكذلك نسجوا منها ثياب هرون المقدسة تماما كما أمر الرب موسى.","39:2":"فنسجوا الرداء من خيوط ذهبية وزرقاء وبنفسجية وحمراء ونسيج الكتان المبروم.","39:3":"وطرقوا الذهب رقائق، وقدوها خيوطا لينسجوها بين الخيوط الزرقاء والبنفسجية والحمراء والكتانية صنعة مطرز حاذق.","39:4":"وصنعوا للرداء كتفين موصولين عند الطرفين ليمكن تثبيته.","39:5":"أما الحزام فقد حيك من ذات نوع القماش، من خيوط ذهبية وزرقاء وحمراء وكتان مبروم تماما كما أمر الرب موسى.","39:6":"وأحاطوا حجري الجزع بطوقين من ذهب نقشت عليهما أسماء أسباط إسرائيل كما ينقش على الخاتم.","39:7":"وتم تثبيتها على كتفي الرداء، كحجري تذكرة ببني إسرائيل، كما أمر الرب موسى.","39:8":"وحاكوا الصدرة حياكة مطرز حاذق من ذات نسيج الرداء من خيوط ذهبية وزرقاء وبنفسجية وحمراء وكتان مبروم.","39:9":"وكانت الصدرة مربعة، طولها شبر وعرضها شبر، ومثنية،","39:10":"مرصعة بأربعة صفوف حجارة كريمة، الصف الأول عقيق أحمر وياقوت أصفر وزمرد.","39:11":"والصف الثاني بهرمان وياقوت أزرق وعقيق أبيض.","39:12":"والصف الثالث عين الهر ويشم وجمشت","39:13":"والصف الرابع زبرجد وجزع ويشب. وكانت كلها محاطة بأطواق من ذهب في ترصيعها.","39:14":"ونقش على كل حجر من الأحجار الكريمة اسم واحد من أسماء أسباط بني إسرائيل الاثني عشر كما ينقش على الخاتم،","39:15":"وصنعوا على الصدرة سلسلتين من ذهب خالص مضفورتين كحبل.","39:16":"وصاغوا طوقين من ذهب وحلقتين ذهبيتين، وثبتوا الحلقتين على طرفي الصدرة.","39:17":"وأدخلوا سلسلتي الذهب في الحلقتين على طرفي الصدرة.","39:18":"وأما طرفا السلسلتين فربطوهما بالطوقين، وثبتوهما على كتفي الرداء من الأمام.","39:19":"كذلك صاغوا حلقتين ذهبيتين وثبتوهما على حاشية طرفي الصدرة الداخلية الملاصقة للرداء.","39:20":"كما صاغوا حلقتين ذهبيتين أخريين، ووضعوهما على أسفل كتفي الرداء من الأمام، عند مكان الوصل فوق حزام الرداء.","39:21":"وربطوا حلقتي الصدرة إلى حلقتي الرداء بخيط أزرق لتثبت فوق حزام الرداء وهكذا لا تنتزع الصدرة عن الرداء، تماما كما أمر الرب موسى.","39:22":"وصنعوا جبة الرداء من قماش أزرق صناعة حائك حاذق،","39:23":"فكان لها فتحة في وسطها على غرار فتحة القميص، ذات حاشية محيطة لئلا تتمزق","39:24":"وجعلوا على استدارة أذيالها رمانات من خيوط كتانية مبرومة زرقاء وبنفسجية وحمراء.","39:25":"وعلقوا بينها أجراسا من ذهب خالص.","39:26":"فكان بين كل رمانتين جرس معلق على استدارة هدب الجبة التي ترتدى في أثناء الخدمة، تماما كما أمر الرب موسى.","39:27":"ونسجوا أقمصة هرون وبنيه من كتان.","39:28":"وكذلك العمامة وعصائب القلانس والسراويل، نسجوها كلها من خيوط الكتان المبرومة.","39:29":"أما الحزام فقد حاكوه من خيوط الكتان المبرومة ذات الألوان الزرقاء والبنفسجية والحمراء، تطريز حائك حاذق، تماما كما أمر الرب موسى.","39:30":"وصنعوا صفيحة الإكليل المقدس من ذهب نقي، ونقشوا عليها كما ينقش على الخاتم: «قدس للرب».","39:31":"وثبتوها بخيط أزرق في مقدمة عمامة هرون تماما كما أمر الرب موسى.","39:32":"وهكذا اكتمل كل بناء مسكن خيمة الاجتماع. فأقامه بنو إسرائيل بموجب ما أمر الرب به موسى.","39:33":"فجاءوا بالمسكن إلى موسى، الخيمة وجميع أوانيها ومشابكها وألواحها وعوارضها وأعمدتها وقواعدها","39:34":"والسقف المصنوع من جلود الكباش المصبوغة باللون البنفسجي، وكذلك السقف المصنوع من جلود الدلفين، والحجاب الفاصل بين القدس وقدس الأقداس،","39:35":"وتابوت الشهادة وعصويه والغطاء،","39:36":"والمائدة مع كل أوانيها وخبز التقدمة،","39:37":"والمنارة الذهبية وسرجها المنضدة مع سائر أوانيها، وزيت إضاءتها،","39:38":"ومذبح الذهب ودهن المسحة، والبخور العطر، وستائر مدخل الخيمة،","39:39":"ومذبح النحاس وشبكته النحاسية، وعصويه، وجميع أوانيه، وحوض الاغتسال وقاعدته،","39:40":"وأستار الساحة وأعمدتها وقواعدها، وستارة باب الساحة وحبالها وأوتادها، وسائر أواني الخدمة المستعملة في خيمة الاجتماع،","39:41":"والثياب المنسوجة التي ترتدى في أثناء الخدمة في المقدس وثياب هرون الكاهن المقدسة، وثياب بنيه الكهنة.","39:42":"وهكذا قام بنو إسرائيل بجميع العمل بمقتضى ما أمر الرب به موسى،","39:43":"فنظر موسى جميع العمل وإذا هم قد صنعوه كما أمر الرب، فباركهم موسى.","40:1":"وقال الرب لموسى:","40:2":"«تقيم مسكن خيمة الاجتماع في اليوم الأول من الشهر الأول (من السنة العبرية).","40:3":"وتضع فيه تابوت الشهادة الذي فيه الوصايا العشر، وتستره بالحجاب.","40:4":"ثم تدخل المائدة وترتب أوانيها عليها، وأيضا المنارة وتضيء سرجها.","40:5":"وتضع مذبح البخور الذهبي أمام تابوت الشهادة القائم وراء الحجاب، وتعلق ستائر باب المسكن.","40:6":"وتجعل مذبح المحرقة النحاسي أمام باب خيمة الاجتماع.","40:7":"ثم تضع حوض الاغتسال بين المسكن والمذبح، واملأه بالماء.","40:8":"وتنصب ستائر الساحة المحيطة بالمسكن، وتعلق ستار مدخلها.","40:9":"وتأخذ دهن المسحة وتمسح به الخيمة وكل ما فيها، وتقدس جميع أوانيها لتكون مخصصة لي.","40:10":"وتمسح أيضا مذبح المحرقة وجميع أوانيه وتقدسه ليكون قدس أقداس.","40:11":"وكذلك تمسح حوض الاغتسال وقاعدته وتقدسه.","40:12":"وتحضر هرون وبنيه إلى مدخل خيمة الاجتماع وتغسلهم بماء.","40:13":"وتلبس هرون ثيابه المقدسة، وتمسحه وتكرسه كاهنا لخدمتي.","40:14":"ثم تحضر بنيه وتلبسهم أقمصتهم أيضا.","40:15":"وتمسحهم كما مسحت أباهم، فيكونون كهنة لي. فتكون هذه المسحة مسحة كهنوت لهم جيلا بعد جيل».","40:16":"ففعل موسى كل ما أمر به الرب.","40:17":"فأقام المسكن في اليوم الأول من الشهر الأول (للسنة العبرية).","40:18":"وصب قواعده ووضع ألواحه وعوارضه، ونصب أعمدته.","40:19":"وبسط السقف فوق المسكن ووضع غطاءه عليه، كما أمره الرب.","40:20":"ثم أخذ لوحي الوصايا العشر ووضعها في التابوت، ووضع العصوين على التابوت من فوق.","40:21":"وحمل التابوت إلى قدس الأقداس، وستر تابوت الشهادة بالحجاب، كما أمره الرب.","40:22":"وأقام المائدة في خيمة الاجتماع في الجانب الشمالي من المسكن خارج الحجاب (أي في القدس).","40:23":"ورتب موسى خبز التقدمة على المائدة أمام الرب، كما أمره.","40:24":"ثم وضع المنارة في خيمة الاجتماع، في الجانب الجنوبي من المسكن مقابل المائدة.","40:25":"وأضاء سرجها أمام الرب كما أمره.","40:26":"ووضع مذبح الذهب في خيمة الاجتماع أمام الحجاب.","40:27":"وأحرق عليه بخورا عطرا، كما أمره الرب.","40:28":"ووضع ستارة على مدخل الخيمة.","40:29":"ووضع مذبح المحرقة عند باب مسكن خيمة الاجتماع. وأصعد عليه المحرقة والتقدمة، كما أمره الرب.","40:30":"ووضع حوض الاغتسال بين خيمة الاجتماع ومذبح المحرقة. وملأه بالماء للاغتسال.","40:31":"ليغسل موسى وهرون وبنوه أيديهم وأرجلهم بمائه.","40:32":"فيغتسلون كلما دخلوا إلى خيمة الاجتماع أو اقتربوا إلى المذبح، كما أمر الرب موسى.","40:33":"ثم نصب موسى جوانب الساحة المحيطة بالمسكن، وعلق ستار مدخلها. وهكذا أكمل موسى العمل.","40:34":"وما لبثت السحابة أن غطت خيمة الاجتماع وملأ جلال الرب المسكن،","40:35":"فلم يستطع موسى دخول خيمة الاجتماع، لأن السحابة حلت عليها، ومجد الرب ملأ المسكن.","40:36":"وكان بنو إسرائيل لا يرتحلون في جميع أسفارهم، إلا إذا ارتفعت السحابة عن المسكن.","40:37":"وإن لم ترتفع، يمكثون حيث هم حتى يوم ارتفاعها.","40:38":"وكانت السحابة تغطي المسكن نهارا، وتتوهج منها نار ليلا، على مرأى كل شعب إسرائيل في جميع رحلاتهم."};
